return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Plugin Search သို့သွားပါ။','Activate %s' => '%s ကို အသက်သွင်းပါ။','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s သည်</strong> <strong>%2$s ကို</strong> ထည့်သွင်းပြီး စတင်အသုံးပြုရန် လိုအပ်သည်။ <a href="%4$s">%3$s</a>','Enter your code here' => 'သင့်ကုဒ်ကို ဤနေရာတွင် ထည့်ပါ။','Add %s' => '%s ကိုထည့်ပါ။','Remove' => 'ဖယ်ရှားပါ။','Order number and receipt will be sent to this email address.' => 'မှာယူမှုနံပါတ်နှင့် ပြေစာကို ဤအီးမေးလ်လိပ်စာသို့ ပေးပို့ပါမည်။','Apartment, unit, building, floor, etc.' => 'တိုက်ခန်း၊ ယူနစ်၊ အဆောက်အအုံ၊ ကြမ်းခင်း စသဖြင့်','Shipping phone' => 'ပို့ဆောင်ခ ဖုန်း','Only used for shipping-related questions.' => 'ပို့ဆောင်ရေးဆိုင်ရာ မေးခွန်းများအတွက်သာ အသုံးပြုသည်။','Single step' => 'တစ်လှမ်းချင်း','Click to go to the order summary' => 'မှာယူမှုအနှစ်ချုပ်သို့သွားရန် နှိပ်ပါ။','Cart total:' => 'လှည်းစုစုပေါင်း-','Proceed to %s' => '%s သို့ ဆက်သွားပါ။','Proceed to contact' => 'ဆက်​သွယ်​ရန်​','Proceed to shipping' => 'ပို့ဆောင်ရန် ဆက်လက်လုပ်ဆောင်ပါ။','Proceed to billing' => 'ငွေတောင်းခံခြင်းသို့ ဆက်သွားပါ။','Proceed to payment' => 'ငွေပေးချေမှုကို ဆက်လက်လုပ်ဆောင်ပါ။','Shipping method' => 'ပို့ဆောင်ရေးနည်းလမ်း','Additional notes' => 'ထပ်လောင်းမှတ်စုများ','Payment method' => 'ငွေပေးချေစနစ်','Step %1$s of %2$s' => '%2$s ၏ အဆင့် %1$s','Change: %s' => 'ပြောင်းလဲခြင်း- %s','Not selected yet.' => 'မရွေးချယ်ရသေးပါ။','Same as shipping address' => 'ပို့ဆောင်ရေးလိပ်စာအတိုင်းပါပဲ။','Same as billing address' => 'ငွေပေးချေရမည့်လိပ်စာနှင့် အတူတူပင်','Order summary' => 'အမိန့်အကျဉ်းချုပ်','Edit cart' => 'လှည်းကို တည်းဖြတ်ပါ။','Did you mean %s?' => '%s ကိုဆိုလိုတာလား။','Change email address to: {suggestion-value}' => 'အီးမေးလ်လိပ်စာကို- {suggestion-value} သို့ ပြောင်းပါ','This is a required field.' => 'ဤသည်မှာ လိုအပ်သောအကွက်တစ်ခုဖြစ်သည်။','This is not a valid email address.' => '၎င်းသည် မှန်ကန်သော အီးမေးလ်လိပ်စာမဟုတ်ပါ။','This field does not match the related field value.' => 'ဤအကွက်သည် သက်ဆိုင်ရာနယ်ပယ်တန်ဖိုးနှင့် မကိုက်ညီပါ။','The CPF number "{cpf_number}" is invalid.' => 'CPF နံပါတ် &quot;{cpf_number}&quot; သည် မမှန်ကန်ပါ။','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ နံပါတ် &quot;{cnpj_number}&quot; သည် မမှန်ကန်ပါ။','(Required)' => '(လိုအပ်သည်)','Checkout Header - Desktop' => 'Checkout Header - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'ကြီးမားသောစခရင်များအတွက် ငွေပေးချေမှုခေါင်းစီးတွင် ဝစ်ဂျက်များကို ပြသပါ။ ပလပ်အင်၏ ငွေပေးချေမှု ခေါင်းစီးကို အသုံးပြုလျှင်သာ ပြသသည်။','Checkout Header - Mobile' => 'ငွေချေမှု ခေါင်းစီး - မိုဘိုင်း','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'မိုဘိုင်းစက်ပစ္စည်းများအတွက် ငွေရှင်းခေါင်းစီးအောက်ရှိ ဝစ်ဂျက်များကို ပြသပါ။ ပလပ်အင်၏ ငွေပေးချေမှု ခေါင်းစီးကို အသုံးပြုလျှင်သာ ပြသသည်။','Checkout Sidebar' => 'ငွေထုတ်ရန် ဘေးဘား','Display widgets on the checkout sidebar after the order summary.' => 'အမှာစာအနှစ်ချုပ်ပြီးနောက် ငွေရှင်းသည့်ဘေးဘားတွင် ဝစ်ဂျက်များကို ပြသပါ။','Checkout Order Summary' => 'ငွေရှင်းရန်အမှာစာအကျဉ်းချုပ်','Display widgets inside the order summary at the checkout page.' => 'ငွေရှင်းသည့်စာမျက်နှာရှိ အမှာစာအနှစ်ချုပ်အတွင်း ဝစ်ဂျက်များကို ပြသပါ။','Checkout Below Place Order' => 'မှာယူမှုအောက်တွင် ငွေရှင်းပါ။','Display widgets below the place order button at the checkout page.' => 'ငွေရှင်းသည့်စာမျက်နှာရှိ နေရာမှာယူမှုခလုတ်အောက်တွင် ဝစ်ဂျက်များကို ပြသပါ။','Checkout Footer' => 'ငွေရှင်းခြင်း အောက်ခြေမှတ်','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'ငွေရှင်းသည့်အောက်ခြေတွင် ဝစ်ဂျက်များကို ပြသပါ။ ပလပ်အင်၏ ငွေပေးချေမှု အောက်ခြေမှတ်စုကို အသုံးပြုလျှင်သာ ပြသသည်။','Classic' => 'ဂန္ထဝင်','Boxed' => 'ထုပ်ပိုးထားသည်။','Split' => 'ကွဲ','Minimalist' => 'ရိုးရှင်းသော','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz မှ Fluid Checkout နှင့် Delivery Date ပလပ်အင်များ','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>CodeRockz မှ WooCommerce (အခမဲ့နှင့် PRO) အတွက် WooCommerce (အခမဲ့နှင့် PRO) အတွက် ပလပ်အင်များ ပေးပို့ခြင်းနှင့် လာယူသည့်နေ့စွဲအချိန်ကို သင်အသုံးပြုနေကြောင်း ကျွန်ုပ်တို့ တွေ့ရှိခဲ့သည်။ ဤပလပ်အင်များနှင့် ပေါင်းစပ်ခြင်းကို Fluid Checkout PRO သို့ ရွှေ့လိုက်ပါပြီ။</p>','Upgrade to PRO' => 'PRO သို့ အဆင့်မြှင့်ပါ။','Fluid Checkout database updated successfully' => 'Fluid Checkout ဒေတာဘေ့စ်ကို အောင်မြင်စွာ မွမ်းမံပြီးပါပြီ။','The database changes where applied successfully.' => 'ဒေတာဘေ့စ်သည် အောင်မြင်စွာ အသုံးချသည့်နေရာကို ပြောင်းလဲသည်။','Dismiss' => 'ပယ်ရန်','Fluid Checkout database update' => 'Fluid Checkout ဒေတာဘေ့စ်အပ်ဒိတ်','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'ဒေတာဘေ့စ်အတွက် အပြောင်းအလဲအချို့ လိုအပ်ပါသည်။ မည်သည့်အပ်ဒိတ်များကဲ့သို့ပင်၊ <strong>ရှေ့ဆက်မလုပ်ဆောင်မီ သင့်ဝဘ်ဆိုဒ်၏ အရန်အပြည့်အစုံကို ယူရန်</strong> ကျွန်ုပ်တို့ အကြံပြုအပ်ပါသည်။','Update database' => 'ဒေတာဘေ့စ်ကို အပ်ဒိတ်လုပ်ပါ။','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout သည် Divi Builder ငွေပေးချေမှု အပြင်အဆင်နှင့် မကိုက်ညီပါ။','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout အလုပ်လုပ်ရန် ဂန္ထဝင် WooCommerce တိုတောင်းသောကုဒ်အခြေခံ ငွေပေးချေမှုပုံစံ လိုအပ်သည်။ ငွေရှင်းသည့်စာမျက်နှာ၏အသွင်အပြင်နှင့် ခံစားချက်ကို စိတ်ကြိုက်ပြင်ဆင်ရန် Divi Builder ကိုအသုံးပြုသည့်အခါ၊ ငွေရှင်းသည့်စာမျက်နှာ၏အစိတ်အပိုင်းတစ်ခုစီအတွက် Divi Builder မှ ဂန္တဝင်ကုဒ်များကို စိတ်ကြိုက်ဝစ်ဂျက်များဖြင့် အစားထိုးပါသည်။ ဤစိတ်ကြိုက်ဝစ်ဂျက်များသည် Fluid Checkout နှင့် သဟဇာတမဖြစ်ပါ။</p><p> Divi Builder ဝစ်ဂျက်များကို တိုတိုကုဒ် <code>[woocommerce_checkout]</code> ပါရှိသော စာသားဝစ်ဂျက်ဖြင့် အစားထိုးသည့် သင်၏ ငွေရှင်းစာမျက်နှာကို တည်းဖြတ်ပါ။</p>','Edit the checkout page' => 'ငွေရှင်းစာမျက်နှာကို တည်းဖြတ်ပါ။','Read the documentation.' => 'စာရွက်စာတမ်းကိုဖတ်ပါ။','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Fluid Checkout ကိုအသုံးပြုသောအခါ Germanized PRO multistep ငွေပေးချေမှုအင်္ဂါရပ်ကိုပိတ်ထားရန်လိုအပ်သည်။','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Fluid Checkout ကိုအသုံးပြုသောအခါ၊ Germanized PRO ပလပ်အင်မှ multistep အင်္ဂါရပ်သည် မလိုအပ်ဘဲဖြစ်လာပြီး <strong>အမှာစာအသစ်များကိုလုပ်ဆောင်နေစဉ်တွင် အရေးကြီးသောအမှားအယွင်းများကို</strong> ဖြစ်စေနိုင်သည်။ ကျေးဇူးပြု၍ ပလပ်အင်ဆက်တင်များတွင် Germanized PRO multistep ငွေရှင်းခြင်းအင်္ဂါရပ်ကို ပိတ်ပါ။','Go to Germanized settings' => 'Germanized ဆက်တင်များသို့ သွားပါ။','Thanks for choosing Fluid Checkout!' => 'Fluid Checkout ကိုရွေးချယ်သည့်အတွက် ကျေးဇူးတင်ပါသည်။','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'သင်သည် ယခု plugin ကို အသုံးပြုနေသည်မှာ ကြာပါပြီ။ အခုထိ ဘယ်လိုကြိုက်လဲ။<br> ကျေးဇူးပြု၍ ကျွန်ုပ်တို့အား အမြန်အဆင့်သတ်မှတ်ပေးပါ၊ တုံ့ပြန်ချက်တိုင်းကို ကျွန်ုပ်တို့ ကျေးဇူးတင်ပါသည်၊ ၎င်းသည် ကျွန်ုပ်တို့အား ပလပ်အင်ကို ဆက်လက်တိုးတက်စေရန် အားပေးပါသည်။ :)','Rate the plugin' => 'ပလပ်အင်ကို အဆင့်သတ်မှတ်ပါ။','I need help!' => 'ကျွန်တော်အကူအညီလိုအပ်တယ်!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Quadlayers မှ WooCommerce Checkout Manager ၏ အချို့သောအင်္ဂါရပ်များသည် Fluid Checkout ဖြင့် ၎င်းကိုအသုံးပြုသည့်အခါ မျှော်လင့်ထားသည့်အတိုင်း အလုပ်မဖြစ်နိုင်ပါ။ နောက်ထပ်အချက်အလက်များနှင့် အခြားရွေးချယ်စရာဖြေရှင်းချက်များအတွက် <a href="%s">ကျွန်ုပ်တို့၏စာရွက်စာတမ်းကို</a> ဖတ်ရှုပါ။','Read documentation' => 'စာတမ်းဖတ်ပါ။','Don\'t show this again' => 'ဒါကို ထပ်မပြပါနဲ့။','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'နောက်ထပ် ဒီဇိုင်းပုံစံများ','Optimized cart page' => 'အကောင်းဆုံးပြင်ဆင်ထားသော လှည်းစာမျက်နှာ','Optimized order received / thank you page' => 'ပိုမိုကောင်းမွန်အောင်ပြုလုပ်ထားသော အော်ဒါလက်ခံရရှိသည်/ကျေးဇူးတင်ပါတယ် စာမျက်နှာ','Edit cart contents at checkout page' => 'ငွေရှင်းခြင်းစာမျက်နှာတွင် စျေးဝယ်ခြင်းအကြောင်းအရာများကို တည်းဖြတ်ပါ။','Account matching / user matching' => 'အကောင့်ကိုက်ညီမှု / အသုံးပြုသူကိုက်ညီမှု','Trust symbols on the cart and thank you pages' => 'လှည်းပေါ်ရှိ သင်္ကေတများနှင့် ကျေးဇူးတင်ကြောင်း စာမျက်နှာများပေါ်တွင် ယုံကြည်ပါ။','More positions for the coupon code on the checkout page' => 'ငွေရှင်းစာမျက်နှာရှိ ကူပွန်ကုဒ်အတွက် နောက်ထပ်ရာထူးများ','International phone numbers' => 'နိုင်ငံတကာဖုန်းနံပါတ်များ','Gift messages and packing slips' => 'လက်ဆောင်စာတိုများနှင့် ထုပ်ပိုးထားသောစာရွက်များ','Local pickup and in-store collection' => 'ဒေသတွင်း လာယူခြင်းနှင့် စတိုးဆိုင်အတွင်း စုဆောင်းခြင်း။','EU-VAT Assistant' => 'EU-VAT လက်ထောက်','I already have it – Hide this offer' => 'ကျွန်ုပ်မှာ ရှိပြီးသားဖြစ်သည် - ဤကမ်းလှမ်းချက်ကို ဝှက်ထားပါ။','Activated' => 'ရပါပြီ။','Address book' => 'လိပ်စာစာအုပ်','Select an image' => 'ပုံတစ်ပုံကို ရွေးပါ။','Cart layout' => 'လှည်းအပြင်အဆင်','Cart optimizations' => 'တွန်းလှည်းကို ဆီလျော်အောင် လုပ်ပါ။','Enable cart page optimizations' => 'စျေးဝယ်စာမျက်နှာ ပိုမိုကောင်းမွန်အောင်ပြုလုပ်ခြင်းကို ဖွင့်ပါ။','Header and footer template' => 'ခေါင်းစီးနှင့် အောက်ခြေ နမူနာပုံစံ','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'အနှောင့်အယှက်ကင်းသော စာမျက်နှာ ခေါင်းစီးနှင့် အောက်ခံကို အသုံးပြုခြင်း ရှိ၊မရှိ သို့မဟုတ် လက်ရှိ အသုံးပြုနေသော အပြင်အဆင်၏ ခေါင်းစီးနှင့် အောက်ခြေကို ထားရှိရန် ထိန်းချုပ်သည်။','Distraction free header and footer' => 'အာရုံထွေပြားမှု ကင်းသော ခေါင်းစီးနှင့် အောက်ခြေ','Theme\'s header and footer' => 'Theme ၏ ခေါင်းစီးနှင့် အောက်ခြေနား','Cart elements' => 'လှည်းဒြပ်စင်','Make the order summary stay visible on the cart page while scrolling' => 'ရွှေ့နေစဉ် အမှာစာအနှစ်ချုပ်ကို လှည်းစာမျက်နှာပေါ်တွင် မြင်နိုင်ပါစေ။','Coupon codes' => 'ကူပွန်ကုဒ်များ','Hidden' => 'ဝှက်ထားသည်။','Before the cart items section' => 'စံနစ်တကျ ပစ္စည်းများကို မှီသည့်အပိုင်း','Inside the cart items section' => 'လှည်းပစ္စည်းများ အပိုင်းအတွင်းပိုင်း','After the cart items section' => 'လှည်းနောက်မှာ ပစ္စည်းအပိုင်း','Before the shipping section' => 'ပို့ဆောင်မှုအပိုင်းကို မမီပါဘူး။','After the shipping section' => 'ပို့ဆောင်မှုအပိုင်းပြီးရင်','Before the order summary' => 'အကျဉ်းချုပ် အမိန့်မချမီ','Inside the order summary' => 'အော်ဒါအနှစ်ချုပ်အတွင်းပိုင်း','Before the order totals' => 'အော်ဒါမတင်မီ','After the order totals' => 'အော်ဒါအပြီးမှာ စုစုပေါင်း','After the order summary' => 'အမိန့်အကျဉ်းချုပ်ပြီးရင်','Shipping' => 'သင်္ဘောဖြင့်ကုန်ပစ္စည်းပို့ခြင်း','Select position where to display the shipping costs and calculator on the cart page.' => 'လှည်းစာမျက်နှာရှိ ပို့ဆောင်ခနှင့် ဂဏန်းတွက်စက်ကို ပြသမည့် နေရာကို ရွေးပါ။','Display as a cart section' => 'လှည်းကဏ္ဍအဖြစ် ပြသပါ။','Cross-sells' => 'ဖြတ်ကျော်ရောင်းချသည်။','Select position where to display the cross-sells section on the cart page.' => 'စျေးဝယ်ခြင်းစာမျက်နှာရှိ အရောင်းအ၀ယ်ကဏ္ဍကို ပြသမည့်နေရာကို ရွေးပါ။','Before the cart actions' => 'လှည်းကိုမှီ၍ ၊','After the cart actions' => 'လှည်းနောက်မှာ ပါက်','Layout of cross-sell items on the cart page.' => 'စျေးဝယ်ခြင်းစာမျက်နှာရှိ ဖြတ်ကျော်ရောင်းချသည့်ပစ္စည်းများ၏ အပြင်အဆင်။','Optimized horizontal cross-sells layout' => 'အလျားလိုက် အပြန်အလှန်ရောင်းချသည့် အပြင်အဆင်ကို အကောင်းဆုံးပြင်ဆင်ထားသည်။','Theme\'s cross-sells layout' => 'အပြင်အဆင်၏ အပြန်အလှန်ရောင်းချမှု အပြင်အဆင်','Number of cross-sell items to display on the cart page' => 'စျေးဝယ်ခြင်းစာမျက်နှာတွင် ပြသရန် ဖြတ်ကျော်ရောင်းချသည့် ပစ္စည်းအရေအတွက်','Add widget areas to the cart page' => 'လှည်းစာမျက်နှာသို့ ဝစ်ဂျက်ဧရိယာများ ထည့်ပါ။','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'ဤဝစ်ဂျက်ဧရိယာများကို လှည်းစာမျက်နှာပေါ်ရှိ ယုံကြည်စိတ်ချရသောသင်္ကေတများနှင့် ယုံကြည်မှုတံဆိပ်များထည့်ရန် အသုံးပြုပါသည်။','Checkout' => 'ထွက်ခွာသည်','Checkout layout' => 'ငွေရှင်းခြင်း အပြင်အဆင်','Design template' => 'ဒီဇိုင်းပုံစံ','Dark mode' => 'အမှောင်မုဒ်','Enable dark mode' => 'အမှောင်မုဒ်ကို ဖွင့်ပါ။','Logo image' => 'လိုဂိုပုံ','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'ငွေရှင်းခြင်း စာမျက်နှာ ခေါင်းစီးတွင် ပြသမည့် ပုံတစ်ပုံကို ရွေးချယ်ပါ။ အာရုံထွေပြားမှုကင်းသော ခေါင်းစီးနှင့် အောက်ခြေနားကို အသုံးပြုသည့်အခါမှသာ အကျုံးဝင်ပါသည်။','Header background color' => 'ခေါင်းစီးနောက်ခံအရောင်','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'ငွေရှင်းခြင်းစာမျက်နှာ ခေါင်းစီးအတွက် နောက်ခံအရောင်ကို ရွေးပါ။ အာရုံထွေပြားမှုကင်းသော ခေါင်းစီးနှင့် အောက်ခြေနားကို အသုံးပြုသည့်အခါမှသာ အကျုံးဝင်ပါသည်။','HTML color value. ie: #f3f3f3' => 'HTML အရောင်တန်ဖိုး။ ဥပမာ- #f3f3f3','Page background color' => 'စာမျက်နှာနောက်ခံအရောင်','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'ငွေရှင်းခြင်းစာမျက်နှာအတွက် နောက်ခံအရောင်ကို ရွေးပါ။ အရောင်သည် <em>ကိုယ်ထည်</em> ဒြပ်စင်သို့ သက်ရောက်သည်။','Footer background color' => 'အောက်ခြေနောက်ခံအရောင်','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'ငွေရှင်းခြင်းစာမျက်နှာအောက်ခြေမှတ်စုအတွက် နောက်ခံအရောင်ကို ရွေးပါ။ အာရုံထွေပြားမှုကင်းသော ခေါင်းစီးနှင့် အောက်ခြေနားကို အသုံးပြုသည့်အခါမှသာ အကျုံးဝင်ပါသည်။','Progress bar' => 'တိုးတက်မှုဘား','Display the checkout progress bar when using multi-step checkout layout' => 'အဆင့်ပေါင်းများစွာ ငွေရှင်းခြင်းအပြင်အဆင်ကို အသုံးပြုသည့်အခါ ငွေရှင်းခြင်းဆိုင်ရာ တိုးတက်မှုဘားကို ပြသပါ။','Make the checkout progress bar stay visible while scrolling' => 'လှိမ့်နေစဉ် ငွေပေးချေမှု တိုးတက်မှုဘားကို မြင်နိုင်ပါစေ။','Express checkout' => 'အမြန်ငွေရှင်းပါ။','Enable the express checkout section' => 'အမြန်ငွေရှင်းမှုအပိုင်းကို ဖွင့်ပါ။','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'ပံ့ပိုးပေးထားသော ငွေပေးချေမှုဂိတ်ဝေးများတွင် ဤအင်္ဂါရပ်ကို ဖွင့်ထားသောအခါ ငွေရှင်းသည့်နေရာတွင် အမြန်ငွေရှင်းသည့်အပိုင်းကို ပြသပါ။','Display express checkout buttons in one line for larger screens' => 'ပိုကြီးသောစခရင်များအတွက် အမြန်ငွေရှင်းရန်ခလုတ်များကို တစ်ကြောင်းတည်းပြသပါ။','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'လိုက်ဖက်ညီသော အမြန်ငွေပေးချေမှုတံခါးပေါက်တစ်ခုဖြင့် ငွေပေးချေသည့်အခါ နောက်ထပ်ငွေရှင်းရန် လိုအပ်သောအကွက်များကို လျစ်လျူရှုပါ။','Make the order summary stay visible while scrolling' => 'ရွှေ့နေစဉ် အမှာစာအနှစ်ချုပ်ကို မြင်အောင်နေပါ။','Choose a background color for the order summary section.' => 'မှာယူမှုအနှစ်ချုပ်ကဏ္ဍအတွက် နောက်ခံအရောင်ကို ရွေးပါ။','Highlight the order totals row in the order summary table' => 'အမှာစာအနှစ်ချုပ်ဇယားရှိ အမှာစာစုစုပေါင်းအတန်းကို မီးမောင်းထိုးပြပါ။','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'မှာယူမှုအနှစ်ချုပ်ကဏ္ဍတွင် မီးမောင်းထိုးထားသည့် နောက်ခံအရောင်မရှိပါက အသုံးဝင်ဆုံးဖြစ်သည်။ Fluid Checkout PRO ကိုအသုံးပြုသည့်အခါ လှည်း၊ အမှာစာလက်ခံရရှိပြီး အမှာစာစာမျက်နှာများကို ကြည့်ပါနှင့်လည်း သက်ဆိုင်နိုင်သည်။','Action link on the order summary at checkout.' => 'ငွေရှင်းချိန်တွင် အမှာစာအနှစ်ချုပ်ရှိ လုပ်ဆောင်ချက်လင့်ခ်။','Edit cart link' => 'လှည်းလင့်ခ်ကို တည်းဖြတ်ပါ။','Cart items count' => 'လှည်းပစ္စည်းများကို ရေတွက်သည်။','Link to shop page' => 'ဆိုင်စာမျက်နှာသို့လင့်ခ်','Cart items' => 'လှည်းပစ္စည်းများ','Hide cart items errors at the checkout page' => 'ငွေရှင်းခြင်းစာမျက်နှာရှိ စျေးဝယ်ပစ္စည်းများ အမှားများကို ဖျောက်ပါ။','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'ငွေရှင်းခြင်းစာမျက်နှာ၏ထိပ်တွင် စျေးဝယ်ပစ္စည်းများ အမှားအယွင်းများ မက်ဆေ့ချ်ကို မပြပါနှင့်။ ဝယ်ယူမှုပြီးမြောက်ရန် ငွေပေးချေမှုပုံစံကို တင်သွင်းသည့်အခါ၊ ဤအမှားမက်ဆေ့ချ်များကို အမြဲတမ်းပြသပါမည်။','Place order' => 'အော်ဒါတင်ပါ။','Define the position to display "Place order" and terms checkbox section.' => '&quot;Place order&quot; နှင့် သတ်မှတ်ချက်များကို checkbox အပိုင်းကို ပြသရန် အနေအထားကို သတ်မှတ်ပါ။','Some options might not be compatible with some plugins and themes.' => 'အချို့သောရွေးချယ်မှုများသည် အချို့သော ပလပ်အင်များနှင့် အပြင်အဆင်များနှင့် တွဲဖက်၍မရပါ။','Below the payment section' => 'ငွေပေးချေမှုအပိုင်းအောက်တွင်','Below the order summary' => 'အမှာစာအကျဉ်းချုပ်အောက်တွင်','Both below the payment section and the order summary' => 'ငွေပေးချေမှုအပိုင်းနှင့် မှာယူမှုအနှစ်ချုပ်အောက်တွင် နှစ်ခုစလုံး','Add widget areas to the checkout page' => 'ငွေရှင်းသည့်စာမျက်နှာသို့ ဝစ်ဂျက်ဧရိယာများထည့်ပါ။','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'ဤဝစ်ဂျက်ဧရိယာများကို ငွေရှင်းသည့်စာမျက်နှာတွင် ယုံကြည်စိတ်ချရသောသင်္ကေတများနှင့် ယုံကြည်မှုတံဆိပ်များထည့်ရန် အသုံးပြုပါသည်။','Display the coupon codes section title' => 'ကူပွန်ကုဒ်များကဏ္ဍ ခေါင်းစဉ်ကို ပြသပါ။','Select position where to display the coupon codes section on the checkout page.' => 'ငွေရှင်းခြင်းစာမျက်နှာရှိ ကူပွန်ကုဒ်များကဏ္ဍကို ပြသမည့် အနေအထားကို ရွေးချယ်ပါ။','Before the checkout steps' => 'ငွေရှင်းရန် ခြေလှမ်းများ မစမီ','As a substep before payment methods' => 'ငွေပေးချေမှုနည်းလမ်းများရှေ့တွင် အဆင့်ခွဲတစ်ခုအနေဖြင့်','As a substep after payment methods' => 'ငွေပေးချေမှုနည်းလမ်းများပြီးနောက် အဆင့်ခွဲတစ်ခုအနေဖြင့်','Default button style' => 'ပုံသေခလုတ်ပုံစံ','"Add" link button' => '&quot;Add&quot; link ကိုနှိပ်ပါ။','Checkout fields' => 'ငွေပေးချေမှုနယ်ပယ်များ','Optional fields' => 'ရွေးချယ်နိုင်သော နယ်ပယ်များ','Hide optional fields behind a link button' => 'လင့်ခ်ခလုတ်တစ်ခု၏နောက်တွင် ရွေးချယ်နိုင်သောအကွက်များကို ဝှက်ထားပါ။','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'အဖွင့်ထည့်သွင်းမှုနယ်ပယ်အရေအတွက်ကို လျှော့ချရန် ဤရွေးချယ်မှုကို ဆက်လက်စစ်ဆေးရန် အကြံပြုလိုသည်၊ <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">သုတေသနကိုဖတ်ပါ</a> ။','Do not hide "Address line 2" fields behind a link button' => 'လင့်ခ်ခလုတ်နောက်ကွယ်တွင် &quot;လိပ်စာလိုင်း 2&quot; အကွက်များကို မဝှက်ပါနှင့်','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'ဝယ်ယူသူအများစုသည် &quot;လိပ်စာလိုင်း 2&quot; အကွက်ကို အမှန်တကယ် လိုအပ်သည့်အခါ သို့မဟုတ် မှန်ကန်သော ပို့ဆောင်ရေးလိပ်စာကို ရရှိသည့်အခါတွင်သာ အရေးကြီးသည် (ဆိုလိုသည်မှာ အစားအသောက်နှင့် အခြားပျက်စီးလွယ်သော ထုတ်ကုန်များကို ပို့ဆောင်ခြင်းဖြစ်ပါက) အကြံပြုထားသည်။','Billing address' => 'ကျသင့်ငွေတောင်းခံလွှာပေးပို့မည့်လိပ်စာ','Select position where to display the billing address section on the checkout page.' => 'ငွေပေးချေမှုစာမျက်နှာရှိ ငွေပေးချေရမည့်လိပ်စာကဏ္ဍကို ပြသမည့် အနေအထားကို ရွေးချယ်ပါ။','As a step before shipping' => 'ပို့ဆောင်ခြင်းမပြုမီ အဆင့်တစ်ခုအနေဖြင့်','As a sub-step before the shipping address section' => 'အဆင့်ခွဲအနေဖြင့် ပို့ဆောင်ရေးလိပ်စာ အပိုင်းကို မှီပါ။','As a sub-step after the shipping address section' => 'အဆင့်ခွဲတစ်ခုအနေဖြင့် သင်္ဘောလိပ်စာကို အပိုင်းလိုက်ပြီးနောက်','As a step after shipping' => 'ပြီးတာနဲ့ အဆင့်တစ်ခုအနေနဲ့ တင်ပါတယ်။','As a sub-step before the payment section' => 'အဆင့်ခွဲအဖြစ် ငွေပေးချေမှုအပိုင်းကို အရင်လုပ်ပါ။','Force billing and shipping addresses to the same (single section)' => 'ငွေတောင်းခံခြင်းနှင့် ပို့ဆောင်ခြင်းလိပ်စာများကို တူညီသော (ကဏ္ဍတစ်ခုတည်း) သို့ အတင်းအကျပ်','Checkbox for "Same as shipping/billing address" checked by default' => 'ပုံမှန်အားဖြင့် &quot;ပို့ဆောင်ခြင်း/ငွေပေးချေသည့်လိပ်စာကဲ့သို့ တူသည်&quot; အတွက် အမှန်ခြစ်ကွက်ကို အမှတ်ခြစ်ထားသည်။','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'ပို့ဆောင်ရေးလိပ်စာအပိုင်းကို ဦးစွာပြသသောအခါ &quot;ပို့ဆောင်ရေးလိပ်စာကဲ့သို့တူညီသည်&quot; အမှတ်ခြစ်ပုံးသည် ပုံသေဖြင့် အမှတ်ခြစ်ထားသည့်အတိုင်း စတင်မည်ဖြစ်သည်။<br> ငွေပေးချေသည့်လိပ်စာအပိုင်းကို ဦးစွာပြသသောအခါ &quot;ငွေပေးချေသည့်လိပ်စာကဲ့သို့တူညီသည်&quot; အမှတ်ခြစ်ကွက်တွင် ပုံသေဖြင့် အမှန်ခြစ်ထားသည့်အတိုင်း စတင်ပါမည်။<br> ငွေရှင်းချိန်တွင် ဖွင့်ထားသောထည့်သွင်းမှုနယ်ပယ်အရေအတွက်ကို သိသိသာသာလျှော့ချရန်အတွက် ဤရွေးချယ်မှုကို အမှန်ခြစ်ထားခဲ့ရန် အကြံပြုလိုသည်၊ <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">သုတေသနကိုဖတ်ပါ</a> ။','Highlight the billing address section in the checkout form' => 'ငွေပေးချေမှုပုံစံတွင် ငွေပေးချေရမည့်လိပ်စာအပိုင်းကို မီးမောင်းထိုးပြပါ။','Shipping address' => 'ကုန်ပစ္စည်းပို့ဆောင်ရမည့်လိပ်စာ','Highlight the shipping address section in the checkout form' => 'ငွေပေးချေမှုပုံစံတွင် သင်္ဘောလိပ်စာအပိုင်းကို မီးမောင်းထိုးပြပါ။','Shipping methods' => 'ပို့ဆောင်ရေးနည်းလမ်းများ','Choose in which position to display the shipping methods section.' => 'ပို့ဆောင်ရေးနည်းလမ်းများကဏ္ဍကိုပြသရန် မည်သည့်အနေအထားတွင် ရွေးချယ်ပါ။','Before shipping address' => 'လိပ်စာမပို့ခင်','After shipping address' => 'ပို့ဆောင်ပြီးနောက်လိပ်စာ','Local pickup' => 'ပြည်တွင်း လာယူပါ။','Removes shipping address section when a local pickup shipping method is selected.' => 'ဒေသအလိုက် လာယူသည့် ပို့ဆောင်ရေးနည်းလမ်းကို ရွေးချယ်သောအခါ ပို့ဆောင်ရေးလိပ်စာအပိုင်းကို ဖယ်ရှားပါ။','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'ဒေသဆိုင်ရာ လာယူသည့် ပို့ဆောင်ရေးနည်းလမ်းကို ရွေးချယ်သောအခါ ပို့ဆောင်မှုလိပ်စာကို မှာယူသည့်နေရာနှင့် အစားထိုးပါ။','Choose which address to save as the shipping address for local pickup orders.' => 'ဒေသတွင်း မှာယူမှုများအတွက် ပို့ဆောင်ရေးလိပ်စာအဖြစ် သိမ်းဆည်းရန် မည်သည့်လိပ်စာကို ရွေးချယ်ပါ။','Save the selected pickup location' => 'ရွေးချယ်ထားသော လာယူမည့်နေရာကို သိမ်းဆည်းပါ။','Save same as the billing address' => 'ငွေတောင်းခံလွှာလိပ်စာအတိုင်း သိမ်းဆည်းပါ။','Do not save any shipping address' => 'မည်သည့်ပို့ဆောင်ရေးလိပ်စာကိုမျှ မသိမ်းဆည်းပါနှင့်','Company name field for shipping address' => 'သင်္ဘောလိပ်စာအတွက် ကုမ္ပဏီအမည်အကွက်','Change visibility for the company name field for the shipping address section on the checkout form.' => 'ငွေရှင်းသည့်ဖောင်ပေါ်ရှိ သင်္ဘောလိပ်စာအပိုင်းအတွက် ကုမ္ပဏီအမည်အကွက်အတွက် မြင်နိုင်စွမ်းကို ပြောင်းပါ။','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'အကွက်ကို ပုံသေမြင်နိုင်မှုအခြေအနေဖြစ်သည့် &quot;ချန်လှပ်ထားနိုင်သည်&quot; ဟု သတ်မှတ်ပါက၊ အခြားပလပ်အင်များသည် ၎င်းတို့လိုအပ်သည့် အပြောင်းအလဲများကို အသုံးချနိုင်စေရန် အပြောင်းအလဲများကို အသုံးချမည်မဟုတ်ပါ။','Hidden (remove field)' => 'ဝှက်ထားသည် (အကွက်ကို ဖယ်ရှားရန်)','Optional' => 'ရွေးချယ်ခွင့်','Required' => 'လိုအပ်သည်။','Add shipping phone field to the checkout form.' => 'ငွေပေးချေမှုဖောင်တွင် ပို့ဆောင်ရေးဖုန်းအကွက်ကို ထည့်ပါ။','Choose in which step to display the shipping phone field.' => 'ပို့ဆောင်ရေးဖုန်းအကွက်ကို ပြသရန် မည်သည့်အဆင့်တွင် ရွေးချယ်ပါ။','Contact step' => 'ဆက်သွယ်ရန်အဆင့်','Billing phone' => 'ဘီလ်ဖုန်း','Add billing phone field to the checkout form.' => 'ငွေပေးချေမှုပုံစံတွင် ဖုန်းငွေပေးချေမှုအကွက်ကို ထည့်ပါ။','Choose in which step to display the billing phone field.' => 'ငွေပေးချေသည့် ဖုန်းအကွက်ကို ပြသရန် မည်သည့်အဆင့်တွင် ရွေးချယ်ပါ။','Show country code beside the flag' => 'အလံဘေးတွင် နိုင်ငံကုဒ်ကို ပြပါ။','Show an example of a valid phone number inside phone fields' => 'ဖုန်းအကွက်များအတွင်း တရားဝင်ဖုန်းနံပါတ်တစ်ခု၏ နမူနာကို ပြပါ။','Do not change placeholders' => 'နေရာယူထားသူများကို မပြောင်းပါနှင့်','Show if not defined' => 'မသတ်မှတ်ရင် ပြပါ။','Always show' => 'အမြဲပြတယ်။','Order notes' => 'အော်ဒါမှတ်စုများ','Define the visibility of the additional order notes field.' => 'ထပ်ဆင့်မှာယူမှုမှတ်စုအကွက်၏ မြင်နိုင်စွမ်းကို သတ်မှတ်ပါ။','Gift options' => 'လက်ဆောင်ရွေးချယ်မှုများ','Allow customers to add a gift message and other gift related options to the order.' => 'ဝယ်ယူသူများအား လက်ဆောင်မက်ဆေ့ဂျ်နှင့် အခြားလက်ဆောင်နှင့်ပတ်သက်သည့် ရွေးချယ်မှုများကို မှာယူမှုတွင် ထည့်သွင်းခွင့်ပြုပါ။','Display the gift message as part of the order details table instead of a separate section' => 'သီးခြားကဏ္ဍအစား အမှာစာအသေးစိတ်ဇယား၏ တစ်စိတ်တစ်ပိုင်းအဖြစ် လက်ဆောင်မက်ဆေ့ဂျ်ကို ပြသပါ။','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'ဤရွေးချယ်မှုသည် မှာယူမှုအတည်ပြုခြင်းစာမျက်နှာ (ကျေးဇူးတင်ပါတယ် စာမျက်နှာ) နှင့် အကောင့်စာမျက်နှာများ၊ အီးမေးလ်များနှင့် ထုပ်ပိုးမှုစာရွက်များရှိ မှာယူမှုအသေးစိတ်အချက်အလက်များကို သက်ရောက်မှုရှိပါသည်။','Account matching' => 'အကောင့်ကိုက်ညီမှု','Enable the account matching feature' => 'အကောင့်ကိုက်ညီသော အင်္ဂါရပ်ကို ဖွင့်ပါ။','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'ဖောက်သည်၏ အဆက်အသွယ်အသေးစိတ်များနှင့် အကောင့်တစ်ခုရှိနှင့်ပြီးဖြစ်သည့်အချိန်တွင် ဧည့်သည်ဖောက်သည်၏အမှာစာများကို ၎င်းတို့၏လက်ရှိအကောင့်နှင့် ချိတ်ဆက်ပါ။','Display message when an account exists with the email address provided' => 'ပေးထားသော အီးမေးလ်လိပ်စာနှင့်အတူ အကောင့်တစ်ခုရှိသည့်အခါ မက်ဆေ့ချ်ကို ပြသပါ။','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'အကောင့်ဖန်တီးမှုအကွက်များကို အကြောင်းကြားချက်နှင့် လော့ဂ်အင်ဝင်ရန် ရွေးချယ်စရာများဖြင့် အစားထိုးသည်။ အချို့အခြေအနေများတွင်၊ သုံးစွဲသူများ၏ လျှို့ဝှက်ရေးလုံခြုံမှုကို ကာကွယ်ရန် ဤရွေးချယ်မှုကို ပိတ်ထားရန် အကြံပြုနိုင်ပါသည်။','Dashboard' => 'ဒိုင်ခွက်','Integrations' => 'ပေါင်းစည်းမှု','License keys' => 'လိုင်စင်သော့များ','Visit our website for more information about our plugins and add-ons.' => 'ကျွန်ုပ်တို့၏ ပလပ်အင်များနှင့် အပိုပရိုဂရမ်များအကြောင်း နောက်ထပ်အချက်အလက်များအတွက် ကျွန်ုပ်တို့၏ဝဘ်ဆိုဒ်သို့ ဝင်ရောက်ကြည့်ရှုပါ။','Order pay page' => 'ငွေပေးချေမှုစာမျက်နှာ','Order pay' => 'အော်ဒါပေးရမယ်။','Enable order pay page optimizations' => 'မှာယူမှု ငွေပေးချေမှု စာမျက်နှာ ပိုမိုကောင်းမွန်အောင် လုပ်ဆောင်မှုများကို ဖွင့်ပါ။','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ဝယ်ယူသူထံမှ ငွေပေးချေမှုကို ဆိုင်းငံ့ထားသည့် လက်ရှိမှာယူမှုများအတွက် မှာယူမှုပေးချေသည့်စာမျက်နှာ၏ အပြင်အဆင်ကို ပြောင်းလဲပါ။','Add widget areas to the order pay page' => 'မှာယူမှုငွေပေးချေမှုစာမျက်နှာသို့ ဝစ်ဂျက်ဧရိယာများထည့်ပါ။','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'ဤဝစ်ဂျက်ဧရိယာများကို မှာယူမှုငွေပေးချေမှုစာမျက်နှာတွင် ယုံကြည်စိတ်ချရသောသင်္ကေတများနှင့် ယုံကြည်မှုတံဆိပ်များထည့်ရန် အသုံးပြုပါသည်။','Thank you page & order details layout' => 'Page &amp; Order အသေးစိတ် အဆင်အပြင်ကို ကျေးဇူးတင်ပါတယ်။','Order details optimizations' => 'မှာယူမှုအသေးစိတ်အား ပိုမိုကောင်းမွန်အောင်ပြုလုပ်ခြင်း။','Enable thank you page and order details optimizations' => 'ကျေးဇူးတင်သော စာမျက်နှာကိုဖွင့်ပြီး မှာယူမှုအသေးစိတ်များကို ပိုမိုကောင်းမွန်အောင်ပြုလုပ်ခြင်း။','Changes the layout of order details on the thank you page and account pages.' => 'ကျေးဇူးတင်သောစာမျက်နှာနှင့် အကောင့်စာမျက်နှာများရှိ မှာယူမှုအသေးစိတ်၏ အပြင်အဆင်ကို ပြောင်းလဲပါ။','Enable order details customizations on email notifications' => 'အီးမေးလ်အကြောင်းကြားချက်များတွင် မှာယူမှုအသေးစိတ် စိတ်ကြိုက်ပြင်ဆင်မှုများကို ဖွင့်ပါ။','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ကဏ္ဍအသစ်များကို ပြသပြီး အီးမေးလ်အကြောင်းကြားချက်များတွင် ကဏ္ဍများကို အစီစဥ်ပြောင်းလဲပါ။ အီးမေးလ်အကြောင်းကြားချက်များရှိ မှာယူမှုအသေးစိတ်ပုံစံများ မပြောင်းလဲပါ။','Thank you page' => 'ကျေးဇူးတင်ပါတယ် စာမျက်နှာ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'ဤရွေးချယ်မှုများသည် မှာယူမှုလက်ခံရရှိခြင်း သို့မဟုတ် မှာယူမှုအတည်ပြုခြင်းစာမျက်နှာများဟုလည်းလူသိများသော ကျေးဇူးတင်သည့်စာမျက်နှာအပေါ် သက်ရောက်မှုရှိသည်။','Order details layout' => 'အော်ဒါအသေးစိတ် အပြင်အဆင်','Display the order details with wide layout on the thank you page' => 'ကျေးဇူးတင်သောစာမျက်နှာတွင် ကျယ်ပြန့်သော အပြင်အဆင်ဖြင့် မှာယူမှုအသေးစိတ်ကို ပြသပါ။','Add widget areas to the thank you page' => 'ကျေးဇူးတင်သောစာမျက်နှာသို့ ဝစ်ဂျက်ဧရိယာများထည့်ပါ။','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'ဤဝစ်ဂျက်ဧရိယာများကို ကျေးဇူးတင်ကြောင်းစာမျက်နှာတွင် ယုံကြည်စိတ်ချရသောသင်္ကေတများနှင့် ယုံကြည်စိတ်ချရသောတံဆိပ်များထည့်ရန် အသုံးပြုပါသည်။','Order actions' => 'အမိန့်ပေးတာတွေ လုပ်တယ်။','Choose in which position to display the order actions.' => 'အမှာစာလုပ်ဆောင်ချက်များကို ပြသရန် မည်သည့်အနေအထားတွင် ရွေးချယ်ပါ။','Inside the order overview' => 'မှာယူမှု ခြုံငုံသုံးသပ်ချက်အတွင်းပိုင်း','After the order overview' => 'အမိန့်ချပြီးနောက်','After order sections' => 'အော်ဒါအပိုင်းတွေပြီးရင်','Order status' => 'အော်ဒါအနေအထား','Display the order status progress bar' => 'မှာယူမှုအခြေအနေ တိုးတက်မှုဘားကို ပြသပါ။','Choose in which position to display the section.' => 'ကဏ္ဍကိုပြသရန် မည်သည့်အနေအထားကို ရွေးချယ်ပါ။','After the order overview and payment instructions' => 'မှာယူမှု ခြုံငုံသုံးသပ်ချက်ပြီးနောက် ငွေပေးချေမှု ညွှန်ကြားချက်များ','Before the order items section' => 'ပစ္စည်းမှာယူမှုအပိုင်းကို မှီပါ။','Inside the order items section' => 'မှာယူမှု ပစ္စည်းများ ကဏ္ဍအတွင်း','After the order items section' => 'အော်ဒါမှာထားတဲ့ ပစ္စည်းတွေ အပိုင်းပြီးသွားပါပြီ။','On the sidebar' => 'ဘေးဘားပေါ်တွင်','Order downloads' => 'ဒေါင်းလုဒ်များ မှာယူပါ။','Gift message' => 'လက်ဆောင်သတင်းစကား','Tools' => 'ကိရိယာများ','Troubleshooting' => 'ပြသာနာရှာဖွေရှင်းပေးခြင်း','Debug options' => 'အမှားရှာပြင်ခြင်း ရွေးစရာများ','Debug mode' => 'အမှားရှာမုဒ်','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'အမှားရှာပြင်မုဒ်ကို အသုံးပြုခြင်းသည် ဝဘ်ဆိုက်စွမ်းဆောင်ရည်ကို ထိခိုက်စေပါသည်။ ပြဿနာဖြေရှင်းနေစဉ်တွင်သာ ဤရွေးချယ်မှုကို အသုံးပြုပါ။','Load unminified assets' => 'မသေးငယ်သောပိုင်ဆိုင်မှုများကို တင်ပါ။','Enhanced select fields' => 'ရွေးချယ်ထားသော အကွက်များကို အဆင့်မြှင့်ထားသည်။','Fix automatic zoom-in on form fields' => 'ဖောင်အကွက်များပေါ်တွင် အလိုအလျောက် ချုံ့ချဲ့ခြင်းအား ပြင်ဆင်ပါ။','Set <code>font-size</code> inside form fields to 16px' => 'ဖောင်အကွက်များအတွင်း <code>font-size</code> ကို 16px သတ်မှတ်ပါ။','Fluid Checkout' => 'Fluid Checkout','Settings' => 'ဆက်တင်များ','Support' => 'အထောက်အပံ့','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'နောက်ထပ်ရွေးချယ်စရာများကို လော့ခ်ဖွင့်ရန် <a target="_blank" href="%s">PRO သို့ အဆင့်မြှင့်ပါ</a> ။','(PRO)' => '(PRO)','(experimental)' => '(စမ်းသပ်မှု)','Please verify your phone number.' => 'သင့်ဖုန်းနံပါတ်ကို အတည်ပြုပါ။','The Bluehost Plugin' => 'Bluehost Plugin','Custom fields' => 'စိတ်ကြိုက်နယ်ပယ်','Enable custom shipping email field' => 'စိတ်ကြိုက်ပို့ဆောင်ရေးအီးမေးလ်အကွက်ကို ဖွင့်ပါ။','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'ဖွင့်ထားသောအခါ၊ Bluehost ပလပ်အင်မှ ပို့ဆောင်ရေးအီးမေးလ်အကွက်ကို ငွေရှင်းသည့်ပုံစံသို့ ပေါင်းထည့်မည်ဖြစ်သည်။','Captcha Pro by BestWebSoft' => 'BestWebSoft မှ Captcha Pro','Captcha position' => 'Captcha အနေအထား','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'captcha အပိုင်းကိုပြသရန် အနေအထားကို သတ်မှတ်ပါ။ ရွေးချယ်ထားသော captcha အမျိုးအစားပေါ်မူတည်၍ အချို့ရာထူးများသည် အလုပ်မဖြစ်နိုင်ပါ။','Selecting a pickup point is required before proceeding.' => 'ဆက်လက်မလုပ်ဆောင်မီ ပစ်မှတ်တစ်ခုကို ရွေးချယ်ရန် လိုအပ်သည်။','Pickup point' => 'ထုတ်ယူရန်အချက်','Pickup point not selected yet.' => 'လာယူမည့်နေရာ မရွေးရသေးပါ။','Pickup point:' => 'လာယူမည့်နေရာ-','Mailchimp for WooCommerce' => 'WooCommerce အတွက် Mailchimp','Subscribe checkbox' => 'စာရင်းသွင်းရန် အမှန်ခြစ်ပေးပါ။','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'ငွေရှင်းသည့်စာမျက်နှာရှိ စာရင်းသွင်းစစ်ဆေးသည့်အကွက်အတွက် အနေအထားကို အစားထိုးပြီး အဆက်အသွယ်အဆင့်တွင် ၎င်းကို အမြဲတမ်းပြသပါ။','Before Shipping Address' => 'သင်္ဘောလိပ်စာ မရောက်မီ','(originally "%s")' => '(မူလက &quot;%s&quot;)','After Shipping Address' => 'ပြီးရင် သင်္ဘောလိပ်စာ','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPoint ဖြင့် ပို့ဆောင်သည့်အခါ စုစည်းမှုအမှတ်ကို ရွေးချယ်ရန် လိုအပ်ပါသည်။','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'အမှန်ခြစ်ထားလျှင် အီးမေးလ်တွင် အမှားအယွင်းများကို သုံးစွဲသူများအား အသိပေးသည်။ (Fluid Checkout လုပ်ဆောင်ချက်ကို ပံ့ပိုးပေးသောကြောင့် ဤအင်္ဂါရပ်ကို ပိတ်ထားသည်။ ဤရွေးချယ်မှုသို့ အပြောင်းအလဲများသည် အကျိုးသက်ရောက်မှု ရှိမည်မဟုတ်ပါ)','Enable Mail Check: (disabled feature)' => 'မေးလ်စစ်ဆေးခြင်းကိုဖွင့်ပါ- (ပိတ်ထားသောအင်္ဂါရပ်)','Carrier:' => 'ဝန်ဆောင်မှုပေးသူ-','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce အီးမေးလ်စျေးကွက်ရှာဖွေရေး','Sign up checkbox position' => 'အမှန်ခြစ်အကွက် အနေအထားကို စာရင်းသွင်းပါ။','Move the sign up checkbox to the contact step' => 'အကောင့်ဖွင့်ရန် အမှန်ခြစ်ကို အဆက်အသွယ်အဆင့်သို့ ရွှေ့ပါ။','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'ဖွင့်ထားသောအခါ၊ အမှန်ခြစ်ဘောက်စ်ကို Sendinblue ပလပ်အင်ဆက်တင်များတွင် သတ်မှတ်ထားသော ပြသတည်နေရာနှင့် သီးခြားအဆက်အသွယ်အဆင့်သို့ ရွှေ့သွားပါမည်။','Theme Betheme' => 'Betheme အပြင်အဆင်','Checkout progress' => 'ငွေထုတ်ခြင်းတိုးတက်မှု','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'ငွေရှင်းရန် အဆင့်များ အပိုင်းကို ငွေရှင်းရန်၊ စျေးဝယ်ခြင်းနှင့် အမှာစာ လက်ခံထားသော စာမျက်နှာများတွင် Betheme မှ ထုတ်နှုတ်ပါ။','Theme Fennik' => 'Theme Fennik','Breadcrumbs' => 'Breadcrumbs','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Fluid Checkout header နှင့် footer ကိုအသုံးပြုသောအခါ Fennik အပြင်အဆင်မှ breadcrumbs အပိုင်းကို ထုတ်ပါ။','Theme Go' => 'အပြင်အဆင်သွားပါ။','My account layout' => 'ကျွန်ုပ်၏အကောင့်အပြင်အဆင်','Enable wide layout on "My account" page.' => '&quot;ကျွန်ုပ်၏အကောင့်&quot; စာမျက်နှာတွင် ကျယ်ပြန့်သော အပြင်အဆင်ကို ဖွင့်ပါ။','Theme Impreza' => 'အပြင်အဆင် Impreza','Header' => 'ခေါင်းစီး','Spacing for site header at the checkout page (in pixels)' => 'ငွေရှင်းစာမျက်နှာရှိ ဆိုက်ခေါင်းစီးအတွက် အကွာအဝေး (ပစ်ဇယ်များ)','Only applicable when using the Impreza theme header at the checkout page.' => 'ငွေရှင်းသည့်စာမျက်နှာရှိ Impreza အပြင်အဆင် ခေါင်းစီးကို အသုံးပြုသည့်အခါသာ သက်ဆိုင်ပါသည်။','Theme Kapee' => 'ကာပီ','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'ငွေပေးချေမှုအဆင့်များအပိုင်းကို ငွေရှင်းရန်၊ စျေးဝယ်ခြင်းနှင့် အမှာစာလက်ခံသည့်စာမျက်နှာများရှိ Kapee အပြင်အဆင်မှ ထုတ်ပေးပါ။','Theme Porto' => 'ဆောင်ပုဒ်ပေါ်တို','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'ငွေပေးချေမှုအဆင့်များကဏ္ဍကို ငွေရှင်းရန်၊ စျေးဝယ်ခြင်းနှင့် မှာယူမှုလက်ခံသည့်စာမျက်နှာများရှိ Porto အပြင်အဆင်မှ ထုတ်ပေးပါ။','Theme Pressmart' => 'Theme Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'ငွေရှင်းခြင်းအဆင့်များအပိုင်းကို ငွေရှင်းရန်၊ စျေးဝယ်ခြင်းနှင့် မှာယူမှုလက်ခံရရှိသည့်စာမျက်နှာများရှိ Pressmart အပြင်အဆင်မှ ထုတ်ပေးပါ။','Theme The Gem' => 'Theme ရတနာ','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Fluid Checkout header နှင့် footer ကိုအသုံးပြုသောအခါ ငွေပေးချေမှုအဆင့်များအပိုင်းကို The Gem အပြင်အဆင်မှ ထုတ်ပါ။','Theme Woodmart' => 'အပြင်အဆင် Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Fluid Checkout header နှင့် footer ကိုအသုံးပြုသောအခါ Woodmart အပြင်အဆင်မှ ငွေရှင်းသည့်အဆင့်များကို ထုတ်ပါ။','Checkout options' => 'ငွေရှင်းရန် ရွေးချယ်မှုများ','Disable the theme checkout options' => 'အပြင်အဆင် ငွေပေးချေမှု ရွေးစရာများကို ပိတ်ပါ။','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'ထုတ်ကုန်ရုပ်ပုံ၊ အရေအတွက်အကွက်ကို ပြသသည့် ရွေးချယ်စရာများ၊ ဖယ်ရှားရန် ခလုတ်နှင့် ထုတ်ကုန်စာမျက်နှာသို့ လင့်ခ်ကို ဆောင်ပုဒ်ဖြင့် ထည့်သွင်းထားသော ရွေးချယ်မှုများကို မူရင်းအားဖြင့် ပိတ်ထားသည်။','Theme Atomion' => 'Theme Atomion','Order progress' => 'အော်ဒါတိုးတက်မှု','Display order progress from the theme' => 'အပြင်အဆင်မှ မှာယူမှုတိုးတက်မှုကို ပြသပါ။','Display the form field labels visible on the page' => 'စာမျက်နှာပေါ်တွင် မြင်နိုင်သော ဖောင်အကွက်အညွှန်းများကို ပြသပါ။','It is recommended to keep this option enabled for a better user experience.' => 'ပိုမိုကောင်းမွန်သော အသုံးပြုသူအတွေ့အကြုံအတွက် ဤရွေးချယ်မှုကို ဆက်လက်ဖွင့်ထားရန် အကြံပြုအပ်ပါသည်။','Theme ZK Nito' => 'အပြင်အဆင် ZK Nito','Add extra fields to the checkout form' => 'ငွေရှင်းသည့်ဖောင်တွင် အပိုအကွက်များထည့်ပါ။','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'ပို့ဆောင်ရေးလိပ်စာအပိုင်းသို့ အပိုပို့ဆောင်ရေးအီးမေးလ်နှင့် ပို့ဆောင်ရေးဖုန်းအကွက်ကို ပေါင်းထည့်ပါ။','Go to the home page' => 'ပင်မစာမျက်နှာကိုသွားပါ။','Skip to content' => 'အကြောင်းအရာသို့ ကျော်သွားပါ။','Create an account' => 'အကောင့်တစ်ခုဖန်တီးသည်','Log in to your account' => 'သင့်အကောင့်သို့ဝင်ရောက်ပါ။','Already have an account?' => 'အကောင့်ရှိပြီးသားလား။','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s အဖြစ် အကောင့်ဝင်ထားသည်။ <a href="%2$s">ထွက်လိုက်ပါ။</a>','Your order has a total amount due of %s. No further payment is needed.' => 'သင့်မှာယူမှုတွင် %s ကြောင့် စုစုပေါင်းပမာဏရှိသည်။ နောက်ထပ်ငွေပေးချေရန်မလိုအပ်ပါ။','Close and continue with checkout' => 'ပိတ်ပြီး ငွေရှင်းခြင်း ဆက်လုပ်ပါ။','Continue' => 'ဆက်ရန်','Parcel terminal' => 'ပါဆယ်ထုပ်ဂိတ်','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>ဤဝစ်ဂျက်ကို Fluid Checkout ဖြင့် အစားထိုးထားသည်။</p><p> Fluid Checkout ကိုအသုံးပြုသည့်အခါ၊ ငွေရှင်းသည့်စာမျက်နှာသည် ကောင်းမွန်စွာအလုပ်လုပ်ရန် မူရင်း WooCommerce တိုတောင်းသောကုဒ် <code>[woocommerce_checkout]</code> ကို အသုံးပြုရန်လိုအပ်သည်။</p><p> ပိုမိုသိရှိလိုပါက၊ Fluid Checkout စာရွက်စာတမ်းအား သွားရောက်ကြည့်ရှုပါ။</p>','Theme The7' => 'Theme ၇','Additional header sections' => 'နောက်ထပ် ခေါင်းစီးကဏ္ဍများ','Output additional header sections if enabled in the theme settings.' => 'အပြင်အဆင်ဆက်တင်များတွင် ဖွင့်ထားပါက အပိုဆောင်းခေါင်းစီးကဏ္ဍများကို ထုတ်ပါ။','More information' => 'အချက်အလက်ပို','Pick a Locker' => 'Locker တစ်ခုကို ရွေးပါ။','Page template' => 'စာမျက်နှာပုံစံ','Use `Order confirmation` page template for block-based themes' => 'block-based themes အတွက် `အော်ဒါအတည်ပြုခြင်း` စာမျက်နှာ နမူနာကို သုံးပါ။','Only applies when using a block-based theme.' => 'ပိတ်ဆို့ခြင်းအခြေခံ အပြင်အဆင်ကို အသုံးပြုသည့်အခါတွင်သာ အကျုံးဝင်ပါသည်။','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'ငွေပေးချေမှုပုံစံ','Apply styles to the Stripe payment form fields' => 'Stripe ငွေပေးချေမှုပုံစံအကွက်များတွင် ပုံစံများကို အသုံးပြုပါ။','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'ဖွင့်ထားသည့်အခါ၊ Fluid Checkout သည် ပလပ်အင်နှင့် လိုက်ဖက်ညီမှုအတွက် အကောင်းဆုံးပြုလုပ်ထားသော ပုံစံများကို အသုံးပြုပါမည်။ Stripe ငွေပေးချေမှုပုံစံအကွက်များအတွက် စိတ်ကြိုက်စတိုင်များကို သင်အသုံးပြုနေပါက ၎င်းကို ပိတ်လိုနိုင်ပါသည်။','Theme Nyture' => 'Theme Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Fluid Checkout ကိုအသုံးပြုသောအခါ Nyture အပြင်အဆင်မှ ငွေရှင်းသည့်အဆင့်များအပိုင်းကို ထုတ်ပါ။','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'စတိုးစီမံခန့်ခွဲသူမှ ကိုယ်တိုင်ဖန်တီးထားသည့် သို့မဟုတ် ငွေရှင်းစဉ်အတွင်း မပြီးပြတ်သည့် အမှာစာများအတွက် သုံးစွဲသူများကို ငွေပေးချေခွင့်ပြုပါ။','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayers မှ WooCommerce Checkout Manager ပလပ်အင်သည် Fluid Checkout နှင့် ကိုက်ညီမှုမရှိပါ။','Company name field for billing address' => 'ငွေတောင်းခံလွှာလိပ်စာအတွက် ကုမ္ပဏီအမည်အကွက်','Change visibility for the company name field for the billing address section on the checkout form.' => 'ငွေရှင်းသည့်ဖောင်ရှိ ငွေပေးချေမှုကဏ္ဍအတွက် ကုမ္ပဏီအမည်အကွက်အတွက် မြင်နိုင်စွမ်းကို ပြောင်းပါ။','Theme Bookshelf' => 'စာအုပ်စင်','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Fluid Checkout ကိုအသုံးပြုသည့်အခါ Bookshelf အပြင်အဆင်မှ ငွေရှင်းသည့်အဆင့်များကို ထုတ်ပါ။','Account password' => 'အကောင့်စကားဝှက်','An account will be created with the information provided at checkout when completing the order.' => 'မှာယူမှုကို ပြီးမြောက်သည့်အခါ ငွေရှင်းချိန်တွင် ပေးထားသည့် အချက်အလက်ဖြင့် အကောင့်တစ်ခု ဖန်တီးပါမည်။','Choose the style of the progress bar.' => 'တိုးတက်မှုဘား၏စတိုင်ကိုရွေးချယ်ပါ။','Bars' => 'အရက်ဆိုင်','Theme Ireca' => 'Theme Ireca','WooCommerce page layout' => 'WooCommerce စာမျက်နှာ အပြင်အဆင်','Force wide layout on WooCommerce pages' => 'WooCommerce စာမျက်နှာများပေါ်တွင် ကျယ်ပြန့်သော အပြင်အဆင်ကို တွန်းအားပေးပါ။','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => '၎င်းသည် ငွေရှင်းခြင်း၊ စျေးဝယ်ခြင်း၊ အမှာစာလက်ခံရရှိခြင်း၊ အော်ဒါပေးချေခြင်းနှင့် အကောင့်စာမျက်နှာများအပါအဝင် WooCommerce စာမျက်နှာများတွင် အကြောင်းအရာအပိုင်းသည် အလွန်ကျဉ်းမြောင်းခြင်းမရှိကြောင်း သေချာစေပါသည်။','WooCommerce Smart Coupons' => 'WooCommerce စမတ်ကူပွန်များ','Position on checkout page' => 'ငွေရှင်းစာမျက်နှာတွင် အနေအထား','Choose where to display the available coupons section on the checkout page.' => 'ငွေရှင်းသည့်စာမျက်နှာရှိ ရနိုင်သောကူပွန်ကဏ္ဍကိုပြသရန်နေရာကိုရွေးချယ်ပါ။','Before the progress bar' => 'တိုးတက်မှုဘားရှေ့','After the progress bar' => 'တိုးတက်မှုဘားပြီးနောက်','Before coupon codes section' => 'ကူပွန်ကုဒ်များ ကဏ္ဍမစမီ','Format phone numbers according to the rules for each country.' => 'နိုင်ငံတစ်ခုစီအတွက် စည်းမျဉ်းများနှင့်အညီ ဖုန်းနံပါတ်များကို ဖော်မတ်လုပ်ပါ။','Use precise phone number validation' => 'တိကျသောဖုန်းနံပါတ်ကို အတည်ပြုခြင်းအား အသုံးပြုပါ။','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => '၎င်းသည် စမ်းသပ်မှုအင်္ဂါရပ်တစ်ခုဖြစ်ပြီး တပ်ဆင်မှုအားလုံးတွင် မျှော်လင့်ထားသည့်အတိုင်း အလုပ်မဖြစ်နိုင်ပါ။ သတိနဲ့သုံးပါ။','Phone number validation types used when precise validation is enabled.' => 'တိကျသောအတည်ပြုချက်ကို ဖွင့်ထားသောအခါတွင် အသုံးပြုသည့် ဖုန်းနံပါတ် မှန်ကန်မှုအမျိုးအစားများ။','Mobile' => 'မိုဘိုင်း','Fixed line' => 'ပုံသေလိုင်း','Toll free' => 'အခမဲ့','Or' => 'သို့မဟုတ်','Contact' => 'ဆက်သွယ်ရန်','Multi step' => 'အဆင့်များစွာ','2 columns' => 'ကော်လံ ၂ ခု','1 column' => '၁ ကော်လံ','Before checkout steps' => 'ငွေရှင်းခြင်းမပြုမီ အဆင့်ဆင့်','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;၁ ကော်လံ&quot;</em> ငွေရှင်းကောင်တာ အပြင်အဆင်ကို အသုံးပြုသည့်အခါ ဤရွေးချယ်မှုကို <em>&quot;ငွေရှင်းကောင်တာအဆင့်များမတိုင်မီ&quot;</em> အဖြစ် အမြဲသတ်မှတ်ထားပြီး ဒက်စ်တော့မြင်ကွင်းအတွက်လည်း အကျုံးဝင်ပါသည်။','Position for the extra order summary section on mobile.' => 'မိုဘိုင်းပေါ်ရှိ အပိုမှာယူမှုအကျဉ်းချုပ်ကဏ္ဍအတွက် ရာထူး။','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;On the site header&quot;</em> ရွေးချယ်မှုသည် အာရုံပျံ့လွင့်မှုကင်းသော header ကိုသုံးသည့်အခါတွင်သာ အကျုံးဝင်ပါသည်။','On the site header (requires distraction-free header)' => 'ဆိုက်ခေါင်းစဉ်တွင် (အာရုံပျံ့လွင့်မှုကင်းသော ခေါင်းစဉ် လိုအပ်သည်)','Initial state for the expansible order summary section on mobile.' => 'မိုဘိုင်းတွင် ချဲ့ထွင်နိုင်သော အော်ဒါအကျဉ်းချုပ်ကဏ္ဍ၏ ကနဦးအခြေအနေ။','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'စည်းမျဉ်းစည်းကမ်း လိုအပ်ချက်များကြောင့် အောက်ပါနိုင်ငံများအတွက် ၎င်းကို <em>တိုးချဲ့ထားသည်</em> အဖြစ် သတ်မှတ်ရန် အကြံပြုပါသည်- <strong>ဂျာမနီ</strong> ၊ <strong>ဩစတြီးယား</strong> ၊ <strong>ဆွစ်ဇာလန်</strong> <strong>၊ နယ်သာလန်</strong> ၊ <strong>ပိုလန်</strong> ၊ <strong>ဘယ်လ်ဂျီယံ</strong> နှင့် <strong>ပြင်သစ်</strong> ။','Collapsed' => 'ခေါက်ထားသည်','Expanded' => 'ချဲ့ထွင်ထားသည်','Do not show' => 'မပြပါနဲ့','yes' => 'ဟုတ်ကဲ့','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ပို့ဆောင်ရေးလိပ်စာအပိုင်းပြီးနောက်တွင် ငွေတောင်းခံလွှာပို့ရမည့်လိပ်စာအပိုင်းကို ပြသထားပြီး ငွေတောင်းခံလွှာပို့ရမည့်ဖုန်းနံပါတ်အပိုင်းကို &quot;လိုအပ်သည်&quot; ဟုသတ်မှတ်ထားပါက ပို့ဆောင်ရေးဖုန်းနံပါတ်အကွက်ကို &quot;လိုအပ်သည်&quot; အဖြစ် အတင်းထည့်သွင်းနိုင်သည်။ ထိုရွေးချယ်မှုကို အမှန်ခြစ်ထားသည့်အခါ ပို့ဆောင်ရေးလိပ်စာကို ငွေတောင်းခံလွှာပို့ရမည့်လိပ်စာသို့ ကူးယူနိုင်ကြောင်း သေချာစေရန်အတွက် ၎င်းကို လိုအပ်ပါသည်၊ မဟုတ်ပါက ဖောက်သည်သည် ငွေရှင်းကောင်တာပုံစံကို ဖြည့်စွက်နိုင်မည်မဟုတ်ပါ။','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ငွေတောင်းခံလွှာပို့ရန်လိပ်စာအပိုင်းကို ပို့ဆောင်ရေးလိပ်စာအပိုင်းမတိုင်မီ ပြသထားပြီး ပို့ဆောင်ရေးဖုန်းနံပါတ်အပိုင်းကို &quot;လိုအပ်သည်&quot; ဟုသတ်မှတ်ထားပါက ငွေတောင်းခံလွှာပို့ရန်ဖုန်းနံပါတ်အကွက်ကို &quot;လိုအပ်သည်&quot; အဖြစ် အတင်းထည့်သွင်းနိုင်သည်။ ထိုရွေးချယ်မှုကို အမှန်ခြစ်ထားသည့်အခါ ပို့ဆောင်ရေးလိပ်စာကို ငွေတောင်းခံလွှာပို့ရန်လိပ်စာသို့ ကူးယူနိုင်ကြောင်း သေချာစေရန်အတွက် ၎င်းကို လိုအပ်ပါသည်၊ မဟုတ်ပါက ဖောက်သည်သည် ငွေရှင်းကောင်တာပုံစံကို ဖြည့်စွက်နိုင်မည်မဟုတ်ပါ။','Settings profiles' => 'ဆက်တင်ပရိုဖိုင်များ','Settings profile' => 'ဆက်တင်ပရိုဖိုင်','You do not have permission to perform this action.' => 'ဤလုပ်ဆောင်ချက်ကို လုပ်ဆောင်ရန် သင်ခွင့်ပြုချက်မရှိပါ။','You do not have permission to activate plugins.' => 'ပလပ်အင်များကို အသက်သွင်းရန် သင်ခွင့်ပြုချက်မရှိပါ။','Missing plugin.' => 'ပလပ်အင် ပျောက်ဆုံးနေသည်။','Plugin activated.' => 'ပလပ်အင်ကို အသက်သွင်းပြီးပါပြီ။','The following changes will be applied:' => 'အောက်ပါပြောင်းလဲမှုများကို သက်ရောက်စေပါမည်-','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Fluid Checkout 5.0 ကတည်းက ဆက်တင်များကို ကွဲပြားစွာ သိမ်းဆည်းထားပါသည်။ လိုအပ်ပါက ယခင်ဗားရှင်းများသို့ အဆင့်မြှင့်တင်နိုင်စေရန် Legacy option များကို database တွင် သိမ်းဆည်းထားဆဲဖြစ်သည်။','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'သင့်စတိုးသည် ဆက်တင်အသစ်များတွင် ၂ ပတ်ခန့် လည်ပတ်နေသောကြောင့် ဒေတာဘေ့စ်တွင် သိမ်းဆည်းထားသော အမွေအနှစ်ရွေးချယ်မှုများကို သင်ရှင်းလင်းနိုင်ပါသည်။ သန့်ရှင်းရေးလုပ်ပြီးနောက် ပလပ်အင်၏ ယခင်ဗားရှင်းများသို့ အဆင့်လျှော့ချရန် လိုအပ်ပါက ဆက်တင်အားလုံးအတွက် မူရင်းတန်ဖိုးများကို အသုံးပြုမည်ဖြစ်ကြောင်း ကျေးဇူးပြု၍ သတိပြုပါ။','Fluid Checkout settings cleanup' => 'Fluid Checkout ဆက်တင်များ ရှင်းလင်းခြင်း','Delete leftover options' => 'ကျန်ရှိသော ရွေးချယ်စရာများကို ဖျက်ပါ','Help us improve Fluid Checkout' => 'Fluid Checkout ကို တိုးတက်ကောင်းမွန်အောင် ကျွန်ုပ်တို့ကို ကူညီပါ။','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'ပိုမိုမြန်ဆန်သော ပံ့ပိုးမှုရရှိရန်နှင့် လိုက်ဖက်ညီမှု တိုးတက်ကောင်းမွန်လာစေရန်နှင့် သက်ရောက်မှုကို တိုင်းတာရန် Fluid Checkout ဖြင့် အမည်မဖော်လိုသော ဆိုက်ပတ်ဝန်းကျင် အစီရင်ခံစာများကို မျှဝေပါ။ ဖောက်သည်၊ အသုံးပြုသူ သို့မဟုတ် အရေးကြီးသော ဒေတာများ မပါဝင်ပါ။ Tools ဆက်တင်များမှ မည်သည့်အရာကိုမဆို မျှဝေမည်ကို သင် အချိန်မရွေး ရွေးချယ်နိုင်ပါသည်။','Enable site environment reports' => 'ဆိုက်ပတ်ဝန်းကျင်အစီရင်ခံစာများကို ဖွင့်ပါ','Review settings' => 'ဆက်တင်များကို ပြန်လည်သုံးသပ်ပါ','This preview has expired. Reload the admin page to start a new preview.' => 'ဤအစမ်းကြည့်ရှုမှု သက်တမ်းကုန်ဆုံးသွားပါပြီ။ အစမ်းကြည့်ရှုမှုအသစ်တစ်ခုစတင်ရန် အက်ဒမင်စာမျက်နှာကို ပြန်လည်စတင်ပါ။','Preview expired' => 'အစမ်းကြည့်ရှုမှု သက်တမ်းကုန်ဆုံးသွားပါပြီ','Orders cannot be placed in the preview.' => 'မှာယူမှုများကို အစမ်းကြည့်ရှုမှုတွင် ထားရှိ၍မရပါ။','Logging in is not available in the preview.' => 'အစမ်းကြည့်ရှုမှုတွင် အကောင့်ဝင်၍မရပါ။','Accounts cannot be created in the preview.' => 'အစမ်းကြည့်ရှုမှုတွင် အကောင့်များကို ဖန်တီး၍မရပါ။','Requests to other sites are blocked in the preview.' => 'အခြားဆိုက်များသို့ တောင်းဆိုမှုများကို အစမ်းကြည့်ရှုမှုတွင် ပိတ်ဆို့ထားသည်။','Processing…' => 'လုပ်ဆောင်နေသည်…','Something went wrong. Please try again.' => 'တစ်စုံတစ်ခု မှားယွင်းနေပါသည်။ ထပ်ကြိုးစားပါ။','Activate plugin' => 'ပလပ်အင်ကို အသက်သွင်းပါ','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - ငွေရှင်းကောင်တာ ပက်ကေ့ချ်အပြည့်အစုံ','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'PRO အင်္ဂါရပ်အားလုံး + add-on အားလုံး၊ တစ်ဈေးတည်း။ တင်းပလိတ်များကို ဒီဇိုင်းဆွဲခြင်း၊ အကောင်းဆုံးဖြစ်အောင်ပြုလုပ်ထားသော လှည်းနှင့် မှာယူမှုလက်ခံရရှိသည့် စာမျက်နှာများ၊ အကောင့်ကိုက်ညီမှုနှင့် အခြားအရာများစွာ။','Optimized order pay page' => 'အကောင်းဆုံးဖြစ်အောင်ပြုလုပ်ထားသော အော်ဒါငွေပေးချေမှုစာမျက်နှာ','Express checkout buttons from supported payment methods' => 'ပံ့ပိုးပေးထားသော ငွေပေးချေမှုနည်းလမ်းများမှ အမြန်ငွေရှင်းခလုတ်များ','Delayed account creation' => 'အကောင့်ဖန်တီးခြင်း နှောင့်နှေးခြင်း','Address autocomplete with Google Maps APIs' => 'Google Maps API များဖြင့် လိပ်စာကို အလိုအလျောက်ဖြည့်စွက်ခြင်း','Multiple saved addresses with the address book' => 'လိပ်စာစာအုပ်ဖြင့် သိမ်းဆည်းထားသော လိပ်စာများစွာ','EU-VAT assistant' => 'EU-VAT လက်ထောက်','Hide this section' => 'ဤအပိုင်းကို ဝှက်ထားပါ','Learn more' => 'ပိုမိုသိရှိရန်','Get early access' => 'အစောပိုင်းဝင်ရောက်ခွင့်ရယူပါ','Activate add-on' => 'အပိုပရိုဂရမ်ကို အသက်သွင်းပါ','Get more out of your checkout journey' => 'သင့်ရဲ့ ငွေရှင်းခရီးစဉ်ကနေ ပိုမိုရယူလိုက်ပါ','Test API key' => 'စမ်းသပ် API ကီး','Guided setup' => 'လမ်းညွှန်စနစ်ထည့်သွင်းခြင်း','Options' => 'ရွေးချယ်စရာများ','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">ငွေရှင်းခြင်း ရွေးချယ်စရာများ</a> တွင် အပြင်အဆင်နှင့် ဒီဇိုင်းကို စီစဉ်သတ်မှတ်ပါ။','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'ဧည့်သည်ငွေရှင်းခြင်းကို ဖွင့်ပြီး/သို့မဟုတ် <a href="%s">ဖောက်သည်အကောင့်ဆက်တင်များကို</a> ပြန်လည်သုံးသပ်ပါ။','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'အကောင်းဆုံးဖြစ်အောင်ပြုလုပ်ထားသော <a href="%1$s">လှည်း</a> ၊ <a href="%2$s">ကျေးဇူးတင်ကြောင်း</a> နှင့် <a href="%3$s">မှာယူမှုငွေပေးချေမှု</a> စာမျက်နှာများကို ဖွင့်ပါ။','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Google Maps မှ <a href="%s">လိပ်စာ အလိုအလျောက်ဖြည့်စွက်ခြင်းကို</a> ဖွင့်ပါ။','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">လိပ်စာစာအုပ်</a> ဖြင့် သိမ်းဆည်းထားသော လိပ်စာများစွာကို ဖွင့်ပါ။','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'သင်ထည့်သွင်းထားသော theme သို့မဟုတ် အခြား plugin များအတွက် ရရှိနိုင်သော <a href="%s">integration option များ</a> ရှိမရှိ စစ်ဆေးပါ။','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'ပိုမိုမြန်ဆန်သော ပံ့ပိုးမှု ရယူပြီး လိုက်ဖက်ညီမှု တိုးတက်ကောင်းမွန်လာစေရန်နှင့် သက်ရောက်မှုကို တိုင်းတာရန် ကျွန်ုပ်တို့ကို ကူညီပါ။ ကိရိယာဆက်တင်များမှ <a href="%s">အသုံးပြုမှုကို ခြေရာခံခြင်းကို ဖွင့်ပါ</a> ။','Missing settings tab.' => 'ဆက်တင် တက်ဘ် ပျောက်ဆုံးနေသည်။','Getting started' => 'စတင်အသုံးပြုခြင်း','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>အံ့သြစရာပါပဲ။ သင့်ရဲ့ ငွေရှင်းစာမျက်နှာကို Fluid Checkout မှာ အခုဖွင့်နေပါပြီ။</strong> စတင်ဖို့အတွက် အဆင့်အနည်းငယ်ကို ဖော်ပြပေးလိုက်ပါတယ်။','Completed' => 'ပြီးစီးပါပြီ','Preview report data' => 'အစီရင်ခံစာဒေတာကို အစမ်းကြည့်ရှုပါ','Send now' => 'ယခုပို့ပါ','Auto-detect' => 'အလိုအလျောက် ရှာဖွေခြင်း','Afrikaans' => 'အာဖရိကန်','Albanian' => 'အယ်လ်ဘေးနီးယား','Amharic' => 'အမ်ဟာရစ်','Arabic' => 'အာရပ်','Armenian' => 'အာမေးနီးယား','Azerbaijani' => 'အဇာဘိုင်ဂျန်','Basque' => 'ဘာ့စ်','Belarusian' => 'ဘီလာရုစ်','Bengali' => 'ဘင်္ဂါလီ','Bosnian' => 'ဘော့စနီးယား','Bulgarian' => 'ဘူလ်ဂေးရီးယား','Burmese' => 'ဗမာလူမျိုး','Catalan' => 'ကက်တလန်','Chinese' => 'တရုတ်','Chinese (Simplified)' => 'တရုတ် (ရိုးရှင်း)','Chinese (Hong Kong)' => 'တရုတ် (ဟောင်ကောင်)','Chinese (Traditional)' => 'တရုတ် (ရိုးရာ)','Croatian' => 'ခရိုအေးရှား','Czech' => 'ချက်','Danish' => 'ဒိန်းမတ်','Dutch' => 'ဒတ်ချ်','English' => 'အင်္ဂလိပ်','English (Australian)' => 'အင်္ဂလိပ် (သြစတြေးလျ)','English (Great Britain)' => 'အင်္ဂလိပ် (ဂရိတ်ဗြိတိန်)','Estonian' => 'အက်စ်တိုးနီးယား','Farsi' => 'ဖာစီ','Finnish' => 'ဖင်လန်','Filipino' => 'ဖိလစ်ပိုင်','French' => 'ပြင်သစ်','French (Canadian)' => 'ပြင်သစ် (ကနေဒါ)','Galician' => 'ဂယ်လီစီယန်','Georgian' => 'ဂျော်ဂျီယာ','German' => 'ဂျာမန်','Greek' => 'ဂရိ','Gujarati' => 'ဂူဂျာရတ်','Hebrew' => 'ဟီးဘရူး','Hindi' => 'ဟိန္ဒီ','Hungarian' => 'ဟန်ဂေရီ','Icelandic' => 'အိုက်စလန်','Indonesian' => 'အင်ဒိုနီးရှား','Italian' => 'အီတလီ','Japanese' => 'ဂျပန်','Kannada' => 'ကန်နာဒါ','Kazakh' => 'ကာဇက်','Khmer' => 'ခမာ','Korean' => 'ကိုရီးယား','Kyrgyz' => 'ကာဂျစ်','Lao' => 'လာအို','Latvian' => 'လတ်ဗီးယား','Lithuanian' => 'လစ်သူယေးနီးယား','Macedonian' => 'မက်ဆီဒိုးနီးယား','Malay' => 'မလေး','Malayalam' => 'မလေးရာလမ်','Marathi' => 'မာရသီ','Mongolian' => 'မွန်ဂိုးလီးယား','Nepali' => 'နီပေါ','Norwegian' => 'နော်ဝေ','Polish' => 'ပိုလန်','Portuguese' => 'ပေါ်တူဂီ','Portuguese (Brazil)' => 'ပေါ်တူဂီ (ဘရာဇီး)','Portuguese (Portugal)' => 'ပေါ်တူဂီ (ပေါ်တူဂီ)','Punjabi' => 'ပန်ချာပီ','Romanian' => 'ရိုမေးနီးယား','Russian' => 'ရုရှား','Serbian' => 'ဆားဘီးယား','Sinhalese' => 'ဆင်ဟာလီစ်','Slovak' => 'ဆလိုဗက်','Slovenian' => 'ဆလိုဗေးနီးယား','Spanish' => 'စပိန်','Spanish (Latin America)' => 'စပိန် (လက်တင်အမေရိက)','Swahili' => 'ဆွာဟီလီ','Swedish' => 'ဆွီဒင်','Tamil' => 'တမီးလ်','Telugu' => 'တယ်လူဂူ','Thai' => 'ထိုင်း','Turkish' => 'တူရကီ','Ukrainian' => 'ယူကရိန်း','Urdu' => 'အူရဒူ','Vietnamese' => 'ဗီယက်နမ်လူမျိုး','Zulu' => 'ဇူးလူး','Google address autocomplete' => 'Google လိပ်စာ အလိုအလျောက်ဖြည့်စွက်ခြင်း','Google Places API version' => 'Google Places API ဗားရှင်း','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Google Places API ရဲ့ ဘယ်ဗားရှင်းကိုသုံးမလဲဆိုတာ ရွေးချယ်ပါ။ Places API အသစ်ကို အမြန်ဆုံးပြောင်းသုံးဖို့ အကြံပြုပါတယ်။','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => '၂၀၂၅ ခုနှစ် မတ်လ ၁ ရက်နေ့မှစ၍ Google သည် &quot;Places API (Legacy)&quot; ဗားရှင်းကို Legacy status သို့ ရွှေ့မည်ဖြစ်သောကြောင့် &quot;Places API (Legacy)&quot; ကို အသုံးပြုရန် အကြံပြုအပ်ပါသည်။ ဆိုလိုသည်မှာ သင်သည် API key အသစ်များအတွက် ဤဝန်ဆောင်မှုကို ဖွင့်နိုင်တော့မည်မဟုတ်ဘဲ API ၏ ထိုဗားရှင်းကို နောက်ဆုံးတွင် ရရှိနိုင်တော့မည်မဟုတ်ပါ။ Legacy API ကိုအသုံးပြုနေသော ရှိပြီးသားအကောင့်များသည် အနှောင့်အယှက်မရှိဘဲ ဆက်လက်အလုပ်လုပ်နိုင်ပါသည်။','(Recommended)' => '(အကြံပြုထားသည်)','Google API key' => 'Google API သော့','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'ဤဝဘ်ဆိုက်အတွက် အလုပ်လုပ်ကြောင်း အတည်ပြုရန် သင့် Google API key ကို ကူးထည့်ပြီး စမ်းသပ်ခလုတ်ကို အသုံးပြုပါ။ key သည် မှန်ကန်ပြီး သင့်ဒိုမိန်းအတွက် ခွင့်ပြုထားကြောင်း သေချာပါစေ၊ မဟုတ်ပါက လိပ်စာအကွက်သည် ဖောက်သည်များ၏ မှာယူမှုများကို ပြီးမြောက်အောင် မလုပ်နိုင်အောင် ပိတ်ဆို့ထားနိုင်သည်။','Enable Google address autocomplete' => 'Google လိပ်စာ အလိုအလျောက်ဖြည့်စွက်ခြင်းကို ဖွင့်ပါ','Enable address autocompletion using the Google Maps APIs.' => 'Google Maps API များကို အသုံးပြု၍ လိပ်စာ အလိုအလျောက်ဖြည့်စွက်ခြင်းကို ဖွင့်ပါ။','Google API language' => 'Google API ဘာသာစကား','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'ဤဘာသာစကားကို Google Places API လိပ်စာအကြံပြုချက်များကိုပြသရန်အသုံးပြုမည်ဖြစ်ပြီး လိပ်စာများကိုလည်း ဤဘာသာစကားဖြင့် အလိုအလျောက်ဖြည့်စွက်ပေးမည်ဖြစ်သည်။','Result types' => 'ရလဒ်အမျိုးအစားများ','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'မည်သည့်ရလဒ်အမျိုးအစားကိုမဆို လက်ခံရန် ဗလာထားခဲ့ပါ၊ ၎င်းသည် ပုံမှန်အားဖြင့် ပိုမိုကောင်းမွန်သော ကိုက်ညီမှုရလဒ်များကို ရရှိစေပါသည်။ <a href="%s" target="_blank">အသေးစိတ်အချက်အလက်များအတွက် စာရွက်စာတမ်းများကို ကြည့်ပါ</a> ။<br> လိပ်စာ အလိုအလျောက်ဖြည့်စွက်သည့် အကွက်များတွင် ပြန်ပေးရန် လိပ်စာရှာဖွေမှုရလဒ် အမျိုးအစား ၅ မျိုးအထိ ရွေးချယ်ပါ။<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ပံ့ပိုးပေးထားသော အမျိုးအစားများ</a> အကြောင်း ပိုမိုလေ့လာရန် Google Maps စာရွက်စာတမ်းကို ဝင်ရောက်ကြည့်ရှုပါ။','Result types (Legacy API)' => 'ရလဒ်အမျိုးအစားများ (Legacy API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (Legacy) ကိုအသုံးပြုသည့်အခါ မည်သည့်လိပ်စာရှာဖွေမှုရလဒ်များကို ပြန်ပေးရမည်။<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">ပံ့ပိုးပေးထားသော အမျိုးအစားများ</a> အကြောင်း ပိုမိုလေ့လာရန် Legacy Google Places API ၏ စာရွက်စာတမ်းကို ဝင်ရောက်ကြည့်ရှုပါ။','Company fields' => 'ကုမ္ပဏီနယ်ပယ်များ','Enable autocomplete for the company name if available' => 'ရရှိနိုင်ပါက ကုမ္ပဏီအမည်အတွက် အလိုအလျောက်ဖြည့်စွက်ခြင်းကို ဖွင့်ပါ','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Google Maps API များမှ ပြန်ပေးသည့်အခါ ကုမ္ပဏီအမည်အချက်အလက်များပါသည့် ကုမ္ပဏီအကွက်၏ အလိုအလျောက်ဖြည့်စွက်ခြင်းကို ဖွင့်ပါ။','Business search' => 'စီးပွားရေးလုပ်ငန်းရှာဖွေခြင်း','Enable search for businesses in the company field' => 'ကုမ္ပဏီနယ်ပယ်ရှိ စီးပွားရေးလုပ်ငန်းများကို ရှာဖွေခွင့်ပြုပါ','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'ကုမ္ပဏီအကွက်တွင် ရိုက်ထည့်သည့်အခါ စီးပွားရေးလုပ်ငန်းနှင့် ဆက်စပ်နေသော လိပ်စာများ၏ အကြံပြုချက်ကို ဖွင့်ပါ၊ ထို့နောက် အကြံပြုချက်များထဲမှ စီးပွားရေးလုပ်ငန်းတစ်ခုကို ရွေးချယ်သည့်အခါ လိပ်စာအကွက်အားလုံးကို အလိုအလျောက်ဖြည့်စွက်ပါ။','Company result types' => 'ကုမ္ပဏီရလဒ်အမျိုးအစားများ','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'အလိုအလျောက်ဖြည့်စွက်ပေးသည့် ကုမ္ပဏီအကွက်များတွင် ပြန်ပေးရန် လိပ်စာရှာဖွေမှုရလဒ် အမျိုးအစား ၅ မျိုးအထိ ရွေးချယ်ပါ။<br> အကြံပြုထားသော တန်ဖိုးမှာ <code>establishment</code> ဖြစ်ပြီး ၎င်းတွင် စီးပွားရေးလုပ်ငန်းအမျိုးအစားအများစု ပါဝင်သည်။<br> စီးပွားရေးလုပ်ငန်းများနှင့် မသက်ဆိုင်သော ရလဒ်များ အပါအဝင် မည်သည့်ရလဒ်အမျိုးအစားကိုမဆို လက်ခံရန် ဗလာထားခဲ့ပါ။<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ပံ့ပိုးပေးထားသော အမျိုးအစားများ</a> အကြောင်း ပိုမိုလေ့လာရန် Google Maps စာရွက်စာတမ်းကို ဝင်ရောက်ကြည့်ရှုပါ။','Google logo' => 'Google လိုဂို','Show text and logo "Powered by Google"' => '&quot;Google မှ ပံ့ပိုးပေးသည်&quot; စာသားနှင့် လိုဂိုကို ပြပါ','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'အမှန်ခြစ်ပေးလိုက်ရင် &quot;Powered by Google&quot; ဆိုတဲ့ စာသားနဲ့ လိုဂိုကို လိပ်စာ အလိုအလျောက်ဖြည့်စွက်ပေးတဲ့ အကြံပြုချက်အကွက်ရဲ့ အောက်ခြေမှာ ပြသပေးပါလိမ့်မယ်။','Brasil API address autocomplete' => 'ဘရာဇီး API လိပ်စာ အလိုအလျောက်ဖြည့်စွက်ခြင်း','Brasil API' => 'ဘရာဇီး API','Enable Brasil API address autocomplete for CEP fields' => 'CEP ကွက်လပ်များအတွက် Brasil API လိပ်စာ အလိုအလျောက်ဖြည့်စွက်ခြင်းကို ဖွင့်ပါ','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/Postcode ကွက်လပ်ကို အသုံးပြု၍ လိပ်စာများကို ပြန်လည်ရယူပြီး အလိုအလျောက်ဖြည့်ရန် Brasil API ကို အသုံးပြုပါ။ ဘရာဇီးလိပ်စာများအတွက်သာ သက်ဆိုင်ပါသည်။','API version' => 'API ဗားရှင်း','Choose which version of the Brasil API CEP method to use.' => 'Brasil API CEP နည်းလမ်း၏ မည်သည့်ဗားရှင်းကို အသုံးပြုမည်ကို ရွေးချယ်ပါ။','Address book migration' => 'လိပ်စာစာအုပ် ရွှေ့ပြောင်းခြင်း','WooCommerce addresses' => 'WooCommerce လိပ်စာများ','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce မှ လက်ရှိ ပို့ဆောင်ရေးနှင့် ငွေတောင်းခံလွှာပို့ လိပ်စာများကို ဖောက်သည်များ၏ လိပ်စာစာအုပ်ထဲသို့ ကူးယူပါ။','Enable the address book feature' => 'လိပ်စာစာအုပ်အင်္ဂါရပ်ကိုဖွင့်ပါ','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'ဖောက်သည်များအား လိပ်စာများစွာကို သိမ်းဆည်းခွင့်ပြုပြီး ပို့ဆောင်ခြင်းနှင့် ငွေတောင်းခံလွှာပို့ခြင်းအတွက် အသုံးပြုမည့် ပုံသေလိပ်စာကို သတ်မှတ်ခွင့်ပြုပါ။','Address labels' => 'လိပ်စာတံဆိပ်များ','Allow customers to add a custom label for each address' => 'ဖောက်သည်များအား လိပ်စာတစ်ခုစီအတွက် စိတ်ကြိုက်အညွှန်းတစ်ခု ထည့်သွင်းခွင့်ပြုပါ','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'လိပ်စာတံဆိပ်များသည် ဖောက်သည်များအတွက် ၎င်းတို့၏ သိမ်းဆည်းထားသော လိပ်စာများ (ဥပမာ- &quot;အမေ့အိမ်&quot;) ကို ခွဲခြားသိရှိရန် ပိုမိုလွယ်ကူစေသည်။ လိပ်စာတံဆိပ်များသည် ဖောက်သည်များအတွက် သီးသန့်ဖြစ်ပြီး မှာယူမှုအသေးစိတ်စာမျက်နှာ သို့မဟုတ် ငွေတောင်းခံလွှာများတွင် ပြသခြင်း သို့မဟုတ် ရိုက်နှိပ်ခြင်း မပြုလုပ်ပါ။','Display layout' => 'မျက်နှာပြင် အပြင်အဆင်','Choose how saved addresses are displayed at checkout and on the cart.' => 'သိမ်းဆည်းထားသော လိပ်စာများကို ငွေရှင်းသည့်အခါနှင့် လှည်းပေါ်တွင် မည်သို့ပြသမည်ကို ရွေးချယ်ပါ။','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'ငွေရှင်းသည့်အခါနှင့် လှည်းပေါ်တွင် အကျုံးဝင်ပါသည်။ အကောင့်စာမျက်နှာတွင် သိမ်းဆည်းထားသော လိပ်စာများသည် ကတ်အပြင်အဆင်ကို အမြဲအသုံးပြုပါသည်။','Address cards' => 'လိပ်စာကတ်များ','Address list' => 'လိပ်စာစာရင်း','Dropdown field' => 'ဒရော့ချ်ဒေါင်း ကွက်လပ်','Address search' => 'လိပ်စာရှာဖွေခြင်း','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'ဖောက်သည်တွင် သိမ်းဆည်းထားသော လိပ်စာအရေအတွက် အနည်းဆုံးရှိပါက frontend တွင် လိပ်စာရှာဖွေမှု filter ကိုပြပါ။','Not used when display layout is set to dropdown field.' => 'မျက်နှာပြင် အပြင်အဆင်ကို dropdown field သို့ သတ်မှတ်ထားသည့်အခါတွင် အသုံးမပြုပါ။','Addresses' => 'လိပ်စာများ','Enable cart page optimizations to see more options' => 'ရွေးချယ်စရာများ ပိုမိုကြည့်ရှုရန် လှည်းစာမျက်နှာ ပိုမိုကောင်းမွန်အောင်ပြုလုပ်ခြင်းကို ဖွင့်ပါ','Sticky order summary' => 'ကပ်ခွာမှာယူမှုအကျဉ်းချုပ်','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'လှည်းစာမျက်နှာတွင် ကူပွန်ကုဒ်ကဏ္ဍကို ပြသမည့်နေရာကို ရွေးချယ်ပါ။ AJAX လှည်းကို ဖွင့်ထားသည့်အခါနှင့် WooCommerce ဆက်တင်တွင် ကူပွန်ကုဒ်များ အသုံးပြုမှုကို ဖွင့်ထားသည့်အခါတွင်သာ သက်ဆိုင်ပါသည်။','Layout of cross-sell' => 'cross-sell ၏ အပြင်အဆင်','Cross-sells displayed' => 'ပြသထားသော cross-selling များ','Items' => 'ပစ္စည်းများ','Cart page optimization' => 'လှည်းစာမျက်နှာ အကောင်းဆုံးဖြစ်အောင်ပြုလုပ်ခြင်း','Give your cart the same clear, conversion-focused layout as your checkout.' => 'သင့်ငွေရှင်းကောင်တာကဲ့သို့ ရှင်းလင်းပြတ်သားပြီး ပြောင်းလဲမှုကို အဓိကထားသော အပြင်အဆင်ကို သင့်လှည်းတွင် ထားပါ။','Match the cart layout to the checkout page for a consistent purchase journey.' => 'ဝယ်ယူမှုခရီးစဉ်ကို တသမတ်တည်းဖြစ်စေရန်အတွက် လှည်းအပြင်အဆင်ကို ငွေရှင်းစာမျက်နှာနှင့် တွဲစပ်ပါ။','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'အရေအတွက်ပြောင်းလဲသည့်အခါ စာမျက်နှာအပြည့် ပြန်လည်တင်ခြင်းမပြုဘဲ လှည်းကို နောက်ခံတွင် အမြဲအပ်ဒိတ်လုပ်ပါ။','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'ကူပွန်ကုဒ်များ၊ ပို့ဆောင်ခြင်းနှင့် cross-selling များကို အကောင်းဆုံးပြောင်းလဲနိုင်သည့်နေရာတွင် ထားပါ။','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'scroll လုပ်နေစဉ် အော်ဒါအကျဉ်းချုပ်ကို မြင်သာအောင်ထားပြီး ဈေးဝယ်သူများ စိတ်ချမှုလိုအပ်သည့်နေရာတွင် ယုံကြည်မှုသင်္ကေတများကို ထည့်ပါ။','Columns' => 'ကော်လံများ','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'ငွေရှင်းခြင်းအဆင့်များ၊ မှာယူမှုအကျဉ်းချုပ်နှင့် အခြားအပိုင်းများအတွက် အထွေထွေစတိုင်များ။ အခြားငွေရှင်းခြင်း၊ လှည်း၊ ကျေးဇူးတင်ကြောင်းပြောခြင်း (လက်ခံရရှိသော မှာယူမှု) နှင့် မှာယူမှုကြည့်ရှုခြင်း စာမျက်နှာများနှင့် သက်ဆိုင်သည်။','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;Split&quot;</em> ဒီဇိုင်း template နှင့်အတူ <em>&quot;1 column&quot;</em> layout ကိုသုံးသည့်အခါ၊ စာမျက်နှာ sidebar widget ဧရိယာ အသက်ဝင်နေမှသာ (Checkout Sidebar၊ Cart Sidebar သို့မဟုတ် Order Received Sidebar) ညာဘက်ကော်လံကို ပြသမည်ဖြစ်သည်။ မဟုတ်ပါက စာမျက်နှာသည် Split style များပါသည့် single column အဖြစ်ရှိနေမည်ဖြစ်သည်။','Split column background' => 'ကော်လံခွဲထားသော နောက်ခံ','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Split design ဒုတိယကော်လံအတွက် နောက်ခံအရောင်ကို ရွေးချယ်ပါ။ အမှာစာအကျဉ်းချုပ် နောက်ခံအရောင်ကို အသုံးပြုရန် ဗလာထားခဲ့ပါ။','Page templates' => 'စာမျက်နှာ တင်းပလိတ်များ','Checkout template' => 'ငွေရှင်းခြင်းပုံစံ','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'ငွေရှင်းသည့်အခါ အာရုံပျံ့လွင့်မှုနည်းပါးစေရန် အကြံပြုထားသည်။ <a href="https://baymard.com/blog/cart-abandonment" target="_blank">လှည်းစွန့်လွှတ်ခြင်းနှင့်ပတ်သက်သည့် သုတေသနကို ဖတ်ရှုပါ</a> ။','Sticky progress bar' => 'ကပ်စေးနေသော တိုးတက်မှုဘား','Progress bar style' => 'တိုးတက်မှုဘားပုံစံ','Order totals' => 'မှာယူမှု စုစုပေါင်း','Background color' => 'နောက်ခံအရောင်','Action link' => 'လုပ်ဆောင်ချက်လင့်ခ်','Mobile order summary' => 'မိုဘိုင်းမှာယူမှုအကျဉ်းချုပ်','Mobile initial state' => 'မိုဘိုင်း ကနဦး အခြေအနေ','Enable editing cart items at checkout' => 'ငွေရှင်းသည့်အခါ လှည်းပစ္စည်းများကို တည်းဖြတ်ခွင့်ပြုပါ','Allow customers to change product quantities or remove items directly at the checkout page.' => 'ဝယ်ယူသူများအား ငွေရှင်းကောင်တာစာမျက်နှာတွင် ထုတ်ကုန်အရေအတွက်များကို ပြောင်းလဲခြင်း သို့မဟုတ် ပစ္စည်းများကို တိုက်ရိုက်ဖယ်ရှားခြင်းတို့ကို ခွင့်ပြုပါ။','Cart item errors' => 'လှည်းပစ္စည်းအမှားများ','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ကူပွန်ကုဒ်ကို checkout သို့မဟုတ် cart စာမျက်နှာများတွင် သီးခြားအပိုင်းတစ်ခုအဖြစ် ပြသထားသည့်အခါနှင့် WooCommerce ဆက်တင်တွင် ကူပွန်ကုဒ်များ အသုံးပြုမှုကို ဖွင့်ထားသည့်အခါတွင်သာ သက်ဆိုင်ပါသည်။','Coupon codes position' => 'ကူပွန်ကုဒ်များ အနေအထား','Apply coupon button' => 'ကူပွန်ခလုတ်ကို အသုံးပြုပါ','Select style of the "apply coupon" button.' => '&quot;ကူပွန်အသုံးပြုပါ&quot; ခလုတ်၏ ပုံစံကို ရွေးချယ်ပါ။','Address line 2' => 'လိပ်စာလိုင်း ၂','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'ဤဆက်တင်ကို Checkout နှင့် Local pickup အပိုင်းများအကြား မျှဝေထားသည်။ Local pickup အပိုင်းတွင်၊ Ship/Pickup ရွေးချယ်ကိရိယာသည် ပို့ဆောင်ရေးနည်းလမ်းအပိုင်းအတွင်း (လိပ်စာမတိုင်မီ) သို့မဟုတ် သီးခြားအပိုင်းတစ်ခုအနေဖြင့် (ပြီးနောက်) ပြသမည်ကိုလည်း ဆုံးဖြတ်သည်။','Customer accounts' => 'ဖောက်သည်အကောင့်များ','Guest checkout' => 'ဧည့်သည်ငွေရှင်းခြင်း','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce အကောင့်ဆက်တင်များစာမျက်နှာမှ ဧည့်သည်ငွေရှင်းခြင်း၊ ဝင်ရောက်ခြင်းနှင့် အကောင့်ဖန်တီးခြင်း ရွေးချယ်စရာများ။ ၎င်းတို့ကို သင့်အတွက်အဆင်ပြေစေရန် ဤနေရာတွင် စီမံခန့်ခွဲထားသောကြောင့် ဆက်တင်ပရိုဖိုင်တစ်ခုစီအတွက် မတူညီသောတန်ဖိုးများကို သင်အသုံးပြုနိုင်သည်။','Allow customers to checkout without an account' => 'အကောင့်မရှိဘဲ ဖောက်သည်များ ငွေရှင်းခွင့်ပြုပါ','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'ငွေရှင်းသည့်အခါ အကောင့်ဖွင့်ရန် သို့မဟုတ် အကောင့်ဝင်ရန် ဖောက်သည်များကို မတောင်းဆိုစေရန် <strong>အကြံပြုထားပြီး</strong> ၎င်းသည် ငွေလဲလှယ်နှုန်းကို လျှော့ချနိုင်စေပါသည်။','When disabled, customers must log in or create an account to complete the purchase.' => 'ပိတ်ထားသည့်အခါ၊ ဝယ်ယူမှုကို ပြီးမြောက်စေရန်အတွက် ဖောက်သည်များသည် ဝင်ရောက်ရမည် သို့မဟုတ် အကောင့်တစ်ခု ဖန်တီးရမည်။','Login at checkout' => 'ငွေရှင်းသည့်အခါ အကောင့်ဝင်ပါ','Enable log-in during checkout' => 'ငွေရှင်းသည့်အခါ အကောင့်ဝင်ခြင်းကို ဖွင့်ပါ','Show a link for returning customers to log in from the checkout page.' => 'ပြန်လည်လာရောက်သော ဖောက်သည်များအတွက် ငွေရှင်းကောင်တာစာမျက်နှာမှ အကောင့်ဝင်ရန် လင့်ခ်တစ်ခုပြပါ။','Account creation' => 'အကောင့်ဖန်တီးခြင်း','Allow customers to create an account during checkout' => 'ငွေရှင်းသည့်အခါ ဖောက်သည်များအား အကောင့်တစ်ခု ဖန်တီးခွင့်ပြုပါ','Customers can create an account before placing their order.' => 'ဖောက်သည်များသည် ၎င်းတို့၏ မှာယူမှုကို မပြုလုပ်မီ အကောင့်တစ်ခု ဖန်တီးနိုင်ပါသည်။','Allow customers to create an account from the My account page' => 'ဖောက်သည်များအား ကျွန်ုပ်၏အကောင့် စာမျက်နှာမှ အကောင့်တစ်ခု ဖန်တီးခွင့်ပြုပါ','Customers can register a new account from the My account page.' => 'သုံးစွဲသူများသည် ကျွန်ုပ်၏အကောင့် စာမျက်နှာမှ အကောင့်အသစ်တစ်ခုကို မှတ်ပုံတင်နိုင်ပါသည်။','Username' => 'အသုံးပြုသူအမည်','Generate from customer\'s name' => 'ဖောက်သည်၏အမည်မှထုတ်လုပ်ပါ','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'ငွေရှင်းသည့်အခါ အသုံးပြုသူအမည်ကို ရွေးချယ်ရန် ဖောက်သည်များကို မတောင်းဆိုစေရန် <strong>အကြံပြုထားပြီး</strong> ၎င်းသည် ပြောင်းလဲမှုနှုန်းကို လျော့ကျစေနိုင်သည်။','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'အသုံးပြုသူအမည်ကို ဖောက်သည်အမည်မှ သို့မဟုတ် အမည်တစ်ခုကို အသုံးမပြုနိုင်သည့်အခါ အီးမေးလ်လိပ်စာမှ ထုတ်ပေးပါသည်။','Password' => 'စကားဝှက်','Send password setup link' => 'စကားဝှက်ထည့်သွင်းမှုလင့်ခ်ပို့ပါ','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'ငွေရှင်းသည့်အခါ ဖောက်သည်များအား စကားဝှက်သတ်မှတ်ရန် မတောင်းဆိုစေရန် <strong>အကြံပြုထားပြီး</strong> ၎င်းသည် ငွေလဲလှယ်နှုန်းကို လျှော့ချနိုင်စေပါသည်။','Customers receive an email to create their password securely.' => 'သုံးစွဲသူများသည် ၎င်းတို့၏ စကားဝှက်ကို လုံခြုံစွာ ဖန်တီးရန်အတွက် အီးမေးလ်တစ်စောင် ရရှိကြသည်။','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'မှတ်ပုံတင်ထားသော ဖောက်သည်များအား အကောင့်ဝင်စရာမလိုဘဲ ငွေရှင်းခြင်းကို အပြီးသတ်နိုင်ပြီး ဆက်သွယ်ရန်အသေးစိတ်အချက်အလက်များ ကိုက်ညီသည့်အခါ ၎င်းတို့၏ရှိပြီးသားအကောင့်နှင့် မှာယူမှုကို ချိတ်ဆက်နိုင်စေပါသည်။','Existing account message' => 'ရှိပြီးသားအကောင့်မက်ဆေ့ချ်','Let customers create an account after placing their order, from the thank you page.' => 'ဖောက်သည်များအား ၎င်းတို့၏ မှာယူမှုကို ပြုလုပ်ပြီးနောက် ကျေးဇူးတင်ကြောင်း စာမျက်နှာမှ အကောင့်တစ်ခု ဖန်တီးခွင့်ပြုပါ။','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'ဤအပိုင်းရှိ ရွေးချယ်စရာများကို ဧည့်သည်ငွေရှင်းခြင်းနှင့် အကောင့်တွဲချိတ်ခြင်းကို ဖွင့်ထားသည့်အခါ ရရှိနိုင်ပါသည်။ နှောင့်နှေးထားသော အကောင့်ဖန်တီးမှုကို စီစဉ်သတ်မှတ်ရန် အထက်ပါ အင်္ဂါရပ်နှစ်ခုလုံးကို ဖွင့်ပါ။','Enable delayed account creation' => 'အကောင့်ဖန်တီးခြင်းကို နှောင့်နှေးခွင့်ပြုပါ','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'ဧည့်သည်ငွေရှင်းခြင်းနှင့် အကောင့်တွဲချိတ်ခြင်း နှစ်မျိုးလုံးကို ဖွင့်ထားသည့်အခါ အကောင့်ဖန်တီးခြင်းကို နှောင့်နှေးပါ။','Section position' => 'ဌာနခွဲ ရာထူး','Before customer details section' => 'ဖောက်သည်အသေးစိတ်အပိုင်းမတိုင်မီ','After customer details section' => 'ဖောက်သည်အသေးစိတ်အပိုင်းပြီးနောက်','Account creation benefits' => 'အကောင့်ဖန်တီးခြင်း၏ အကျိုးကျေးဇူးများ','Leaving the field empty will display the default text.' => 'အကွက်ကို ဗလာထားခဲ့ခြင်းဖြင့် မူရင်းစာသားကို ပြသပေးပါမည်။','Inline buttons' => 'လိုင်းခလုတ်များ','Required fields' => 'လိုအပ်သောအကွက်များ','Enable gift message fields at checkout' => 'ငွေရှင်းသည့်အခါ လက်ဆောင်မက်ဆေ့ချ်အကွက်များကို ဖွင့်ပါ','Expanded gift message' => 'လက်ဆောင်မက်ဆေ့ချ်ကို ချဲ့ထွင်ထားသည်','Display gift message field always expanded' => 'လက်ဆောင်မက်ဆေ့ချ်ပြကွက်ကို အမြဲတမ်းချဲ့ထွင်ထားသည်','Gift message in order details' => 'လက်ဆောင်မက်ဆေ့ချ်မှာယူမှုအသေးစိတ်','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'ဤအပိုင်းတွင် လောလောဆယ်တွင် ပေါင်းစပ်မှုများ မရှိပါ။ ပလပ်အင် သို့မဟုတ် အပြင်အဆင်တစ်ခုစီနှင့် သက်ဆိုင်သည့် ရွေးချယ်စရာများသည် ထိုပလပ်အင် သို့မဟုတ် အပြင်အဆင်ကို အသက်သွင်းသည့်အခါတွင်သာ ဤနေရာတွင် ပေါ်လာမည်ဖြစ်သည်။','Phone fields' => 'ဖုန်းကွင်းများ','Field visibility' => 'လယ်ကွင်းမြင်သာမှု','Field position' => 'ကွင်းအနေအထား','Phone country code & validation' => 'ဖုန်းနိုင်ငံကုဒ်နှင့် အတည်ပြုချက်','Country' => 'နိုင်ငံ','Enable country on phone fields' => 'ဖုန်းကွက်လပ်များတွင် နိုင်ငံကို ဖွင့်ပါ','Filter countries for shipping or billing' => 'ပို့ဆောင်ခြင်း သို့မဟုတ် ငွေတောင်းခံလွှာပို့ခြင်းအတွက် နိုင်ငံများကို စစ်ထုတ်ပါ','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'ဖုန်းအကွက်တစ်ခုစီရှိ နိုင်ငံရွေးချယ်မှုကို သင့်စတိုးတွင် ပို့ဆောင်ခြင်း သို့မဟုတ် ငွေတောင်းခံလွှာပို့ခြင်းအတွက် ခွင့်ပြုထားသော နိုင်ငံများအတွင်းသာ ကန့်သတ်ပါ။','Validation' => 'အတည်ပြုခြင်း','Enable simple validation based on country rules' => 'နိုင်ငံစည်းမျဉ်းများအပေါ် အခြေခံ၍ ရိုးရှင်းသော အတည်ပြုချက်ကို ဖွင့်ပါ','Checks that the phone number is valid for the selected country, including country code and length.' => 'နိုင်ငံကုဒ်နှင့် အရှည်အပါအဝင် ရွေးချယ်ထားသော နိုင်ငံအတွက် ဖုန်းနံပါတ်သည် မှန်ကန်မှုရှိမရှိ စစ်ဆေးသည်။','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'ရွေးချယ်ထားသော နိုင်ငံတွင် မှန်ကန်သော မိုဘိုင်း၊ ကြိုးဖုန်း သို့မဟုတ် အခြားလက်ခံထားသော အမျိုးအစား ဟုတ်မဟုတ်ကို ပိုမိုတင်းကျပ်စွာ စစ်ဆေးပါ။ မှန်ကန်သော နံပါတ်အချို့ကို ငြင်းပယ်နိုင်ပါသည်။','Validation types' => 'အတည်ပြုချက် အမျိုးအစားများ','Placeholders' => 'နေရာချန်လှပ်ထားမှုများ','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'လောလောဆယ်တွင် စီမံခန့်ခွဲရန် လိုင်စင်ကီးများ မရှိပါ။ လိုင်စင်ရ Fluid Checkout plugin သို့မဟုတ် add-on အသက်ဝင်နေချိန်တွင် လိုင်စင်ကီးများသည် ဤနေရာတွင် ပေါ်လာပါမည်။','Default delivery type' => 'ပုံသေ ပို့ဆောင်မှု အမျိုးအစား','Choose which delivery type will be selected by default.' => 'မူရင်းအားဖြင့် မည်သည့်ပို့ဆောင်မှုအမျိုးအစားကို ရွေးချယ်မည်ကို ရွေးချယ်ပါ။','Shipping zone fields' => 'သင်္ဘောဇုန် လယ်ကွင်းများ','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'ဒေသတွင်း လာယူပို့ဆောင်ရေးဇုန် စစ်ထုတ်ကွက်လပ်များအတွက် ပြသမည့်ကွက်လပ်များကို ရွေးချယ်ပါ။ ရရှိနိုင်သော ရွေးချယ်စရာအားလုံးကို ပြသရန် ဗလာထားခဲ့ပါ။','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'ဤအကွက်များကို ဒေသတွင်း လာယူပို့ဆောင်မှုနည်းလမ်းများအတွက် filter အဖြစ် ပြသပါမည်။ တွဲဖက်အသုံးပြုနိုင်သော plugin များက ၎င်းတို့ ကောင်းမွန်စွာအလုပ်လုပ်ရန် လိုအပ်ပါက ဤနေရာတွင် ရွေးချယ်မထားသော်လည်း အချို့အကွက်များကို ငွေရှင်းသည့်အခါတွင် ပေါ်လာနိုင်သေးသည်။','Order shipping address' => 'မှာယူမှုပို့ဆောင်ရေးလိပ်စာ','Order pay page optimization' => 'အော်ဒါငွေပေးချေမှုစာမျက်နှာ အကောင်းဆုံးဖြစ်အောင်ပြုလုပ်ခြင်း','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'မပေးရသေးသော မှာယူမှုများကို ငွေရှင်းကောင်တာကဲ့သို့ပင် ရှင်းလင်းပြတ်သားပြီး ပြောင်းလဲမှုကို အဓိကထားသော အပြင်အဆင်ကို ပေးပါ။','Optimize the layout of the order pay page for orders pending payment.' => 'ငွေပေးချေမှု ဆိုင်းငံ့ထားသော မှာယူမှုများအတွက် မှာယူမှုငွေပေးချေမှု စာမျက်နှာ၏ အပြင်အဆင်ကို အကောင်းဆုံးဖြစ်အောင် ပြုလုပ်ပါ။','Match the order pay experience to your checkout for a consistent purchase journey.' => 'ဝယ်ယူမှုခရီးစဉ်ကို တသမတ်တည်းဖြစ်စေရန်အတွက် မှာယူမှုငွေပေးချေမှုအတွေ့အကြုံကို သင်၏ငွေရှင်းကောင်တာနှင့် တွဲစပ်ပါ။','Add trust symbols and badges where shoppers need reassurance before paying.' => 'ငွေပေးချေခြင်းမပြုမီ ဝယ်ယူသူများ စိတ်ချမှုလိုအပ်သည့်နေရာတွင် ယုံကြည်မှုသင်္ကေတများနှင့် တံဆိပ်များထည့်ပါ။','Thank you page optimization' => 'စာမျက်နှာ အကောင်းဆုံးဖြစ်အောင်ပြုလုပ်ခြင်းအတွက် ကျေးဇူးတင်ပါသည်','Make the thank you page and order details clearer for customers after they buy.' => 'ဖောက်သည်များ ဝယ်ယူပြီးနောက် ကျေးဇူးတင်ကြောင်း စာမျက်နှာနှင့် မှာယူမှုအသေးစိတ်အချက်အလက်များကို ပိုမိုရှင်းလင်းစွာ ဖော်ပြပါ။','Optimize the thank you page and account order details with a clearer layout.' => 'ကျေးဇူးတင်ကြောင်း စာမျက်နှာနှင့် အကောင့်အမှာစာ အသေးစိတ်အချက်အလက်များကို ပိုမိုရှင်းလင်းသော အပြင်အဆင်ဖြင့် အကောင်းဆုံးဖြစ်အောင်ပြုလုပ်ပါ။','Show order status progress, actions, downloads, and notes where they make sense.' => 'မှာယူမှုအခြေအနေ တိုးတက်မှု၊ လုပ်ဆောင်ချက်များ၊ ဒေါင်းလုဒ်များနှင့် မှတ်စုများကို အဓိပ္ပာယ်ရှိရှိ ပြသပါ။','Customize order details sections on email notifications.' => 'အီးမေးလ်အကြောင်းကြားချက်များရှိ မှာယူမှုအသေးစိတ်ကဏ္ဍများကို စိတ်ကြိုက်ပြင်ဆင်ပါ။','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'ဝယ်ယူပြီးနောက် ဝယ်ယူသူများ စိတ်ချမှုလိုအပ်သည့်နေရာတွင် ယုံကြည်မှုသင်္ကေတများနှင့် တံဆိပ်များထည့်ပါ။','Email notifications' => 'အီးမေးလ်အကြောင်းကြားချက်များ','Enable thank you page and order details optimizations to see more options' => 'ရွေးချယ်စရာများ ပိုမိုကြည့်ရှုရန် ကျေးဇူးတင်ကြောင်း စာမျက်နှာနှင့် မှာယူမှုအသေးစိတ်အချက်အလက်များ အကောင်းဆုံးဖြစ်အောင်ပြုလုပ်ခြင်းကို ဖွင့်ပါ။','Use wide layout on thank you page' => 'ကျေးဇူးတင်ကြောင်း စာမျက်နှာတွင် ကျယ်ပြန့်သော အပြင်အဆင်ကို အသုံးပြုပါ','These options affect the thank you page, view order details on account pages and on email notifications.' => 'ဤရွေးချယ်မှုများသည် ကျေးဇူးတင်ကြောင်း စာမျက်နှာကို သက်ရောက်မှုရှိပြီး အကောင့်စာမျက်နှာများနှင့် အီးမေးလ်အကြောင်းကြားချက်များတွင် မှာယူမှုအသေးစိတ်အချက်အလက်များကို ကြည့်ရှုပါ။','Save settings' => 'ဆက်တင်များကို သိမ်းဆည်းပါ','Docs' => 'စာရွက်စာတမ်းများ','Cart' => 'လှည်း','Thank you' => 'ကျေးဇူးတင်ပါသည်','Address autocomplete' => 'လိပ်စာ အလိုအလျောက်ဖြည့်စွက်ခြင်း','Trust badges' => 'ယုံကြည်မှု တံဆိပ်များ','You do not have permission to save these settings.' => 'ဤဆက်တင်များကို သိမ်းဆည်းရန် သင်ခွင့်ပြုချက်မရှိပါ။','Invalid save request.' => 'သိမ်းဆည်းရန် တောင်းဆိုချက် မမှန်ကန်ပါ။','Your settings have been saved.' => 'သင့်ဆက်တင်များကို သိမ်းဆည်းပြီးပါပြီ။','Saving...' => 'သိမ်းဆည်းနေသည်...','Settings could not be saved. Please try again.' => 'ဆက်တင်များကို သိမ်းဆည်း၍မရပါ။ ထပ်မံကြိုးစားပါ။','Dismiss notice' => 'အသိပေးချက်ကို ပယ်ချပါ','Open settings menu' => 'ဆက်တင်မီနူးကို ဖွင့်ပါ','Close settings menu' => 'ဆက်တင်မီနူးကို ပိတ်ပါ','Preview' => 'အစမ်းကြည့်ရှုခြင်း','Expand preview' => 'အစမ်းကြည့်ရှုမှုကို ချဲ့ထွင်ပါ','Collapse preview' => 'အစမ်းကြည့်ရှုမှုကို ခေါက်သိမ်းပါ','Show header and footer' => 'ခေါင်းစီးနှင့် အောက်ခြေပြပါ','Hide header and footer' => 'header နှင့် footer ကို ဝှက်ပါ','Page preview' => 'စာမျက်နှာ အစမ်းကြည့်ရှုခြင်း','Preview viewport' => 'မြင်ကွင်းပေါက်ကို အစမ်းကြည့်ရှုခြင်း','Tablet' => 'တက်ဘလက်','Desktop' => 'ဒက်စ်တော့','Preview width' => 'အစမ်းကြည့်ရှုမှု အကျယ်','Decrease width' => 'အကျယ်ကို လျှော့ချပါ','Preview width in pixels' => 'ပစ်ဆယ်ဖြင့် အစမ်းကြည့်ရှုခြင်း အကျယ်','Increase width' => 'အကျယ်ကို တိုးမြှင့်ပါ','Preview as' => 'အစမ်းကြည့်ရှုခြင်းအဖြစ်','Guest' => 'ဧည့်သည်','Logged in' => 'လော့ဂ်အင်ဝင်ပြီးပါပြီ','Preview page' => 'စာမျက်နှာကို အစမ်းကြည့်ရှုပါ','Expand preview for a closer look' => 'အနီးကပ်ကြည့်ရှုရန် preview ကိုချဲ့ပါ','Available with %s.' => '%s ဖြင့် ရရှိနိုင်ပါသည်။','Turn them on' => '၎င်းတို့ကို ဖွင့်ပါ','Optimizations for this page are turned off. %s to preview the page.' => 'ဤစာမျက်နှာအတွက် အကောင်းဆုံးဖြစ်အောင်ပြုလုပ်မှုများကို ပိတ်ထားသည်။ စာမျက်နှာကို ကြိုတင်ကြည့်ရှုရန် %s။','%s preview' => '%s အစမ်းကြည့်ရှုခြင်း','Isolated session · nothing is saved' => 'သီးခြားအစည်းအဝေး · ဘာမှမသိမ်းဆည်းပါ','Usage tracking' => 'အသုံးပြုမှုကို ခြေရာခံခြင်း','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Fluid Checkout ၏ လိုက်ဖက်ညီမှုကို မြှင့်တင်ရန်အတွက် အာရုံခံနိုင်စွမ်းမရှိသော ဆိုက်ပတ်ဝန်းကျင် အစီရင်ခံစာများ ပေးပို့ပါ။ အောက်ပါ ရွေးချယ်စရာများတွင် မဖွင့်မချင်း အစီရင်ခံစာများကို မပို့ပါ။','Send usage tracking reports to Fluid Checkout' => 'အသုံးပြုမှုခြေရာခံခြင်းအစီရင်ခံစာများကို Fluid Checkout သို့ပေးပို့ပါ','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'ဤအစီရင်ခံစာများကို သင့်ဆိုက်အတွက် လိုက်ဖက်ညီမှုနှင့် ပံ့ပိုးမှုတိုးတက်စေရန် ကျွန်ုပ်တို့အား ကူညီပေးပြီး ဖွင့်ထားသည့်အခါ အပတ်စဉ် ပေးပို့ပါသည်။','No customer, admin user, or any other sensitive data is included in the reports.' => 'အစီရင်ခံစာများတွင် မည်သည့်ဖောက်သည်၊ အက်ဒမင်အသုံးပြုသူ သို့မဟုတ် အခြားအရေးကြီးသောဒေတာကိုမျှ မထည့်သွင်းထားပါ။','Basic environment info' => 'အခြေခံပတ်ဝန်းကျင်အချက်အလက်','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'WordPress၊ PHP၊ WooCommerce၊ theme နှင့် plugin စာရင်းဒေတာ။ အစီရင်ခံခြင်းကိုဖွင့်ထားသည့်အခါတိုင်း ထည့်သွင်းထားသည်။ သင့်ဆိုက်လည်ပတ်နေသောပတ်ဝန်းကျင်ကို ကျွန်ုပ်တို့နားလည်ရန် ကူညီပေးသည်။','Plugin settings' => 'ပလပ်အင်ဆက်တင်များ','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'ပံ့ပိုးမှုတောင်းဆိုမှုများအတွက် ကူညီပေးရန်နှင့် ကျွန်ုပ်တို့၏ ပလပ်အင်များကို သင်မည်သို့အသုံးပြုနေသည်ကို နားလည်ရန် Fluid Checkout ပလပ်အင်ဆက်တင်များကို ပေးပို့သည်။','Coming soon' => 'မကြာမီလာမည်','Sales metrics' => 'ရောင်းအား မက်ထရစ်များ','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Fluid Checkout ကို မထည့်သွင်းမီ ယနေ့အထိ တစ်နှစ်တာအတွက် လစဉ် မှာယူမှုအရေအတွက်နှင့် စုစုပေါင်းရောင်းအား။ ကျွန်ုပ်တို့၏ ပလပ်အင်များကို ထည့်သွင်းခြင်းဖြင့် သင်ပိုမိုငွေရှာနေသလားဆိုသည်ကို နားလည်ရန် ကူညီပေးသည်။ ဖောက်သည် သို့မဟုတ် အသုံးပြုသူဒေတာကို ဘယ်သောအခါမှ မပေးပို့ပါ။','Utilities' => 'အသုံးအဆောင်များ','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> အစား <code>TomSelect</code> dropdown components များကိုသုံးပါ','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect သည် Select2 ထက် အမှားအယွင်းနည်းပါးသော်လည်း လုပ်ဆောင်ချက်တူညီသော dropdown ရွေးချယ်မှုအစိတ်အပိုင်းတစ်ခုဖြစ်သည်။','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'သေးငယ်သော စက်ပစ္စည်းများပေါ်ရှိ ဖောင်အကွက်များနှင့် အပြန်အလှန်ဆက်သွယ်သည့်အခါ အလိုအလျောက် zoom လုပ်ခြင်းကို ရှောင်ရှားရန် ဤ plugin မှ optimize လုပ်ထားသော စာမျက်နှာများတွင် form field များအတွင်းရှိ ဖောင့်အရွယ်အစားကို 16px သို့ သတ်မှတ်သည်။','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'ဖောင့်အရွယ်အစား 16px ထက်သေးငယ်သည့်အခါ စာသားကိုဖတ်ရလွယ်ကူစေရန် Safari နှင့် အခြားဘရောက်ဆာများသည် မိုဘိုင်းစက်ပစ္စည်းများတွင် အလိုအလျောက် zoom in လုပ်နိုင်ပါသည်။','Enable script processing tracking on the browser console.' => 'browser console မှာ script processing tracking ကို enable လုပ်ပါ။','Unminified assets' => 'မကန့်သတ်ထားသော ပိုင်ဆိုင်မှုများ','Google Maps scripts' => 'Google Maps script များ','Do not remove duplicate Google Maps scripts' => 'ထပ်နေသော Google Maps script များကို မဖယ်ရှားပါနှင့်','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'ဖွင့်ထားသည့်အခါ အမှားအယွင်းများနှင့် စွမ်းဆောင်ရည်ပြဿနာများ ဖြစ်စေနိုင်သည့် ထပ်နေသော Google Maps script များကို မဖယ်ရှားပါ။ ဤရွေးချယ်မှုကို ပြဿနာရှာဖွေဖြေရှင်းနေစဉ်တွင်သာ အသုံးပြုပါ။','Widget areas' => 'ဝစ်ဂျက်ဧရိယာများ','Last step on mobile' => 'မိုဘိုင်းပေါ်တွင် နောက်ဆုံးခြေလှမ်း','Display widgets only at last step on mobile' => 'မိုဘိုင်းတွင် နောက်ဆုံးအဆင့်တွင်သာ ဝစ်ဂျက်များကို ပြသပါ','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'မိုဘိုင်းစက်ပစ္စည်းများတွင် နောက်ဆုံးငွေရှင်းသည့်အဆင့်ကို ကြည့်ရှုသည့်အခါတွင်သာ ငွေရှင်းခြင်းယုံကြည်မှုတံဆိပ်ဝစ်ဂျက်များကို ပြသပါ။','Standard' => 'စံ','VAT number field' => 'VAT နံပါတ် အကွက်','Add a VAT number field to the billing form.' => 'ငွေတောင်းခံလွှာပုံစံတွင် VAT နံပါတ်အကွက်ကို ထည့်ပါ။','Field label' => 'လယ်ကွင်းအညွှန်း','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'VAT နံပါတ်အကွက်၏ အညွှန်းကို သတ်မှတ်ပါ (ဆိုလိုသည်မှာ VAT နံပါတ်)။ ဘာသာစကားများစွာပါဝင်သော ဝဘ်ဆိုက်များတွင် ဤအကွက်ကို ဗလာထားခဲ့ပြီး မူရင်းစာကြောင်းကို ဘာသာပြန်ဆိုခြင်းက ပိုကောင်းပါသည်။','VAT Number' => 'VAT နံပါတ်','EU-VAT' => 'EU-VAT','Enable the VAT number field to see more options' => 'ရွေးချယ်စရာများ ပိုမိုကြည့်ရှုရန် VAT နံပါတ်အကွက်ကို ဖွင့်ပါ','VAT validation' => 'VAT အတည်ပြုချက်','Validate VAT number field for EU-VAT during checkout' => 'ငွေရှင်းသည့်အခါ EU-VAT အတွက် VAT နံပါတ်အကွက်ကို အတည်ပြုပါ','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'ပေးထားသော VAT နံပါတ်သည် European VIES Database (VAT Information Exchange System) တွင် မှတ်ပုံတင်ထားသော တရားဝင် VAT နံပါတ် ဟုတ်မဟုတ် စစ်ဆေးသည်။','Shop VAT number' => 'ဆိုင် VAT နံပါတ်','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'EU-VAT အတည်ပြုချက်ကို တောင်းဆိုရန်အတွက် အသုံးပြုပြီး ငွေတောင်းခံလွှာများတွင် ရိုက်နှိပ်ထားသော ဆိုင်၏ VAT နံပါတ်။<br> မဟုတ်ပါက VIES တိုင်ပင်ဆွေးနွေးမှုရလဒ်များသည် စာရင်းကိုင်ရည်ရွယ်ချက်အတွက် မှန်ကန်မည်မဟုတ်သောကြောင့် <strong>သင့်ဆိုင် VAT နံပါတ်ကို ထည့်သွင်းရန် အထူးအကြံပြုအပ်ပါသည်</strong> ။<br> ဆိုလိုသည်မှာ <code>ATU99999999</code> သို့မဟုတ် <code>EE999999999</code> ။','Reverse charge' => 'ပြောင်းပြန်အားသွင်းခြင်း','Apply reverse charge mechanism' => 'ပြောင်းပြန်အားသွင်းယန္တရားကို အသုံးချပါ','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'ဖောက်သည်၏ VAT နံပါတ် မှန်ကန်ပါက အခွန်နှုန်းကို သုညအဖြစ် သတ်မှတ်ပြီး ပြေစာများတွင် &quot;Reverse charge&quot; ကို ပြသပါ။ စတိုးဆိုင်၏ နိုင်ငံပေါ် မူတည်၍ မတူညီသော &quot;Reverse charge&quot; စာသား လိုအပ်နိုင်ပါသည်။','Same country' => 'နိုင်ငံတူ','Apply reverse charge mechanism for transactions in the shop country:' => 'ဆိုင်နိုင်ငံတွင် ငွေပေးငွေယူများအတွက် ပြောင်းပြန်ငွေကောက်ခံသည့် ယန္တရားကို ကျင့်သုံးပါ-','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'ဆိုင်နှင့် တူညီသောနိုင်ငံတွင် ကုမ္ပဏီများအကြား ငွေပေးငွေယူများအတွက် ပြောင်းပြန်ငွေကောက်ခံမှုယန္တရားကို အသုံးချနိုင်စေပါသည်။','Reverse charge exceptions' => 'ပြောင်းပြန်ကောက်ခံမှု ခြွင်းချက်များ','Select additional countries to skip applying the reverse charge mechanism.' => 'ပြောင်းပြန်ငွေကောက်ခံမှုယန္တရားကို အသုံးမပြုရန် နောက်ထပ်နိုင်ငံများကို ရွေးချယ်ပါ။','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'တရားဝင် VAT နံပါတ် ပေးထားသော်လည်း ဤနိုင်ငံများမှ မှာယူမှုများအတွက် အခွန်ကောက်ခံမည်ဖြစ်သည်။','Reverse charge label on invoices' => 'ငွေတောင်းခံလွှာများပေါ်ရှိ ပြောင်းပြန်ကောက်ခံမှုတံဆိပ်','Set the label of "reverse charge" on the checkout page and order details.' => 'ငွေရှင်းကောင်တာစာမျက်နှာတွင် &quot;ပြောင်းပြန်ငွေကောက်ခံမှု&quot; ဟူသော အညွှန်းတပ်ပြီး မှာယူမှုအသေးစိတ်ကို ထည့်ပါ။','Reverse charge text on invoices' => 'ငွေတောင်းခံလွှာများပေါ်ရှိ ပြောင်းပြန်ကောက်ခံမှုစာသား','Set the label of "reverse charge" text on invoices.' => 'ငွေတောင်းခံလွှာများတွင် &quot;ပြောင်းပြန်ကောက်ခံမှု&quot; စာသား၏ အညွှန်းကို သတ်မှတ်ပါ။','Tax to be paid on reverse charge basis' => 'ပြောင်းပြန်ကောက်ခံမှုအခြေခံဖြင့် ပေးဆောင်ရမည့်အခွန်','Company name' => 'ကုမ္ပဏီအမည်','Autocomplete company name from VAT number' => 'VAT နံပါတ်မှ ကုမ္ပဏီအမည်ကို အလိုအလျောက်ဖြည့်စွက်ပါ','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'ဖောက်သည်မှ ပေးထားသော တရားဝင် VAT နံပါတ်အပေါ် အခြေခံ၍ ငွေတောင်းခံလွှာပို့သည့် ကုမ္ပဏီအမည်ကို ဖြည့်ပါ။','Company name editing' => 'ကုမ္ပဏီအမည်တည်းဖြတ်ခြင်း','Allow editing of auto-filled company name' => 'အလိုအလျောက်ဖြည့်ထားသော ကုမ္ပဏီအမည်ကို တည်းဖြတ်ခွင့်ပြုပါ','When enabled, customers can change the company name associated with the provided VAT number.' => 'ဖွင့်ထားသည့်အခါ ဖောက်သည်များသည် ပေးထားသော VAT နံပါတ်နှင့် ဆက်စပ်နေသော ကုမ္ပဏီအမည်ကို ပြောင်းလဲနိုင်သည်။','EU-VAT for digital goods' => 'ဒစ်ဂျစ်တယ်ကုန်ပစ္စည်းများအတွက် EU-VAT','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '၂၀၁၅ ခုနှစ်၊ ဇန်နဝါရီလ ၁ ရက်နေ့မှစ၍ ဒစ်ဂျစ်တယ်ကုန်ပစ္စည်းများနှင့်ပတ်သက်သည့် EU VAT စည်းမျဉ်းများကို ပြင်ဆင်မှုများပြုလုပ်ခဲ့ပြီး B2C ငွေပေးငွေယူများကိုသာ သက်ရောက်မှုရှိသည်။ ဒစ်ဂျစ်တယ်ကုန်ပစ္စည်းများအပေါ် VAT ကို ဖောက်သည်၏တည်နေရာအပေါ် အခြေခံ၍ တွက်ချက်ရမည်ဖြစ်ပြီး ၎င်း၏အထောက်အထားများ (IP လိပ်စာနှင့် ငွေတောင်းခံလွှာလိပ်စာ) ကို စုဆောင်းရန် လိုအပ်ပါသည်။','Tax classes for digital goods' => 'ဒစ်ဂျစ်တယ်ကုန်ပစ္စည်းများအတွက် အခွန်အမျိုးအစားများ','Select some tax classes' => 'အခွန်အမျိုးအစားအချို့ကို ရွေးချယ်ပါ','Location evidence' => 'တည်နေရာအထောက်အထား','Collect customer\'s location evidence' => 'ဖောက်သည်၏ တည်နေရာအထောက်အထားများကို စုဆောင်းပါ','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP လိပ်စာကို သိမ်းဆည်းပြီး ဖောက်သည်၏ ငွေတောင်းခံလွှာပို့သည့်လိပ်စာနှင့် တိုက်ဆိုင်စစ်ဆေးပါသည်။ ဖောက်သည်များသည် ၎င်းတို့၏ ငွေတောင်းခံလွှာပို့သည့်လိပ်စာနှင့် IP မှ နိုင်ငံ မကိုက်ညီပါက ငွေရှင်းကောင်တာစာမျက်နှာရှိ အကွက်တစ်ခုကို အမှန်ခြစ်ခြင်းဖြင့် ၎င်းတို့၏ ငွေတောင်းခံလွှာပို့သည့်လိပ်စာကို အတည်ပြုရမည်။','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'ဤရွေးချယ်မှုကို Fluid Checkout တွင် စီမံခန့်ခွဲသည်။ <a href="%s">၎င်းကို Customer accounts setting တွင် ပြောင်းလဲပါ</a> ။','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'ဤရွေးချယ်မှုကို Fluid Checkout တွင် စီမံခန့်ခွဲသည်။ ၎င်းကို Fluid Checkout &gt; Customer accounts အောက်တွင် ပြောင်းလဲပါ။','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'ဤရွေးချယ်မှုကို Fluid Checkout တွင် စီမံခန့်ခွဲသည်။ Fluid Checkout ကို အသက်သွင်းသည့်အခါ ပို့ဆောင်မည့်နေရာသည် &quot;ဖောက်သည်ပို့ဆောင်ရေးလိပ်စာသို့ ပုံသေ&quot; အဖြစ် အမြဲသတ်မှတ်ထားသည်။ ဖောက်သည်များသည် ငွေရှင်းသည့်အခါ မတူညီသော ပို့ဆောင်ရေးနှင့် ငွေတောင်းခံလွှာလိပ်စာများကို ပေးနိုင်ပါသည်။<br><br> ပုံသေငွေတောင်းခံလွှာလိပ်စာကို ပို့ဆောင်ရေးလိပ်စာနှင့် အတူတူဖြစ်အောင် သတ်မှတ်ရန် ရွေးချယ်မှုတစ်ခုကို <a href="%s">Fluid Checkout ဆက်တင်</a> များတွင် ရရှိနိုင်ပါသည်။','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'ဤရွေးချယ်မှုကို Fluid Checkout တွင် စီမံခန့်ခွဲသည်။ Fluid Checkout ကို အသက်သွင်းသည့်အခါ ပို့ဆောင်မည့်နေရာသည် &quot;ဖောက်သည်ပို့ဆောင်ရေးလိပ်စာသို့ ပုံသေ&quot; အဖြစ် အမြဲသတ်မှတ်ထားသည်။ ဖောက်သည်များသည် ငွေရှင်းသည့်အခါ မတူညီသော ပို့ဆောင်ရေးနှင့် ငွေတောင်းခံလွှာလိပ်စာများကို ပေးနိုင်ပါသည်။<br><br> ပုံသေငွေတောင်းခံလွှာလိပ်စာကို ပို့ဆောင်ရေးလိပ်စာနှင့် တူညီအောင် သတ်မှတ်ရန် ရွေးချယ်မှုတစ်ခုကို WooCommerce &gt; Settings &gt; Fluid Checkout တွင် ရရှိနိုင်ပါသည်။','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'ဤဆက်တင်များကို WP Admin &gt; Fluid Checkout &gt; Settings သို့ ရွှေ့လိုက်ပါပြီ။','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'ဤ WooCommerce Settings tab ကို ရပ်ဆိုင်းလိုက်ပြီဖြစ်ပြီး Fluid Checkout 6.0 တွင် ဖယ်ရှားလိုက်ပါမည်။','Go to settings page' => 'ဆက်တင်စာမျက်နှာသို့ သွားပါ','Hide this tab permanently' => 'ဤတဘ်ကို အပြီးအပိုင် ဝှက်ထားပါ','Site report preview' => 'ဆိုက်အစီရင်ခံစာ အစမ်းကြည့်ရှုခြင်း','This is the data that would be included in the next site environment report based on your current settings.' => 'ဒါက သင့်ရဲ့လက်ရှိဆက်တင်များအပေါ် အခြေခံပြီး နောက်လာမယ့်ဆိုက်ပတ်ဝန်းကျင်အစီရင်ခံစာမှာ ထည့်သွင်းမယ့်ဒေတာပါ။','Loading report preview...' => 'အစီရင်ခံစာ အစမ်းကြည့်ရှုခြင်းကို တင်နေသည်...','Could not load the site report preview. Try again.' => 'ဆိုက်အစီရင်ခံစာ အစမ်းကြည့်ရှုခြင်းကို တင်၍မရပါ။ ထပ်မံကြိုးစားပါ။','Could not send the site report. Try again.' => 'ဆိုက်အစီရင်ခံစာကို ပို့၍မရပါ။ ထပ်မံကြိုးစားပါ။','Site report sent successfully.' => 'ဆိုက်အစီရင်ခံစာကို အောင်မြင်စွာ ပေးပို့ပြီးပါပြီ။','Enable and send now' => 'ဖွင့်ပြီး ယခုပို့ပါ','Close' => 'ပိတ်ရန်','A site report request is already in progress. Try again in a moment.' => 'ဆိုက်အစီရင်ခံစာတောင်းဆိုမှုကို လုပ်ဆောင်နေပါပြီ။ ခဏနေမှ ထပ်ကြိုးစားပါ။','Site environment reporting is disabled.' => 'ဆိုက်ပတ်ဝန်းကျင် အစီရင်ခံခြင်းကို ပိတ်ထားသည်။','No site report data is available to send.' => 'ပေးပို့ရန် ဆိုက်အစီရင်ခံစာဒေတာ မရှိပါ။','This site domain cannot send environment reports (local or development domains are excluded).' => 'ဤဆိုက်ဒိုမိန်းသည် ပတ်ဝန်းကျင်အစီရင်ခံစာများကို ပေးပို့၍မရပါ (ဒေသတွင်း သို့မဟုတ် ဖွံ့ဖြိုးတိုးတက်ရေးဒိုမိန်းများကို ချန်လှပ်ထားပါသည်)။','A site report was sent recently. Try again later.' => 'မကြာသေးမီက ဆိုက်အစီရင်ခံစာတစ်စောင် ပေးပို့ခဲ့ပါသည်။ နောက်မှ ထပ်မံကြိုးစားပါ။','The site report could not be sent. Try again later.' => 'ဆိုက်အစီရင်ခံစာကို ပို့၍မရပါ။ နောက်မှ ထပ်မံကြိုးစားပါ။','Site environment reporting is not available.' => 'ဆိုက်ပတ်ဝန်းကျင် အစီရင်ခံခြင်းကို ရရှိနိုင်မည်မဟုတ်ပါ။','No site report data is available for the selected settings.' => 'ရွေးချယ်ထားသော ဆက်တင်များအတွက် ဆိုက်အစီရင်ခံစာဒေတာ မရရှိနိုင်ပါ။','You are not allowed to manage site reports.' => 'ဆိုက်အစီရင်ခံစာများကို စီမံခန့်ခွဲခွင့်မရှိပါ။','PRO feature' => 'PRO အင်္ဂါရပ်','Other plugins' => 'အခြားပလပ်အင်များ','Get only this add-on &mdash; %s' => 'ဤ add-on ကိုသာ ရယူပါ — %s','Install add-on' => 'အပိုပရိုဂရမ် ထည့်သွင်းပါ','Upgrade to PRO &mdash; %s' => 'PRO သို့ အဆင့်မြှင့်တင်ပါ — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'ဤရွေးချယ်စရာများကို လော့ခ်ဖွင့်ရန် <a target="_blank" href="%1$s">%2$s ကို ရယူပါ</a> ။','Add-on' => 'ဖြည့်စွက်မှု','View documentation' => 'စာရွက်စာတမ်းများကို ကြည့်ရှုပါ','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'တောင်းဆိုချက်များတွင် လော့ဂ်အင်ဝင်ထားသော WordPress အသုံးပြုသူ လိုအပ်ပါသည်။ လက်ရှိအသုံးပြုသူ၏ဒေတာကိုအသုံးပြုရန် user_id ကိုချန်ထားပါ၊ သို့မဟုတ် ဖုန်းခေါ်ဆိုသူသည် ထိုအသုံးပြုသူကို တည်းဖြတ်နိုင်သည့်အခါ အခြားအကောင့်ကို ပစ်မှတ်ထားရန် user_id ကို ပေးပို့ပါ (edit_user စွမ်းရည်)။ အထောက်အထားမခိုင်လုံသော တောင်းဆိုမှုများသည် fc_api_forbidden ကို ပြန်ပို့သည်။ မမှန်ကန်သော user_id သည် fc_api_user_not_found ကို ပြန်ပို့သည်။','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'handler သည် payload ကို ပြန်ပေးသည့်အခါ { &quot;data&quot;: { ... } } ဖြင့် HTTP 200။','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'payload မရှိသည့်အခါ (ဥပမာ DELETE) HTTP 200 တွင် { &quot;success&quot;: true } ဖြင့် လုပ်ဆောင်သည်။','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'WP_Error (ကုဒ်၊ မက်ဆေ့ချ်၊ data.status) မှ WordPress REST အမှား JSON ကို ပြန်ပေးသည့် ပျက်ကွက်မှုများ။ ဝါယာကြိုးကုဒ်များသည် fc_api_* ရှေ့ဆက်ကို အသုံးပြုသည်။','Forbidden access.' => 'တားမြစ်ထားသော ဝင်ရောက်ခွင့်။','Target user was not found.' => 'ပစ်မှတ်အသုံးပြုသူကို ရှာမတွေ့ပါ။','This feature is not available.' => 'ဤအင်္ဂါရပ်ကို ရရှိနိုင်ခြင်းမရှိပါ။','A required address field is missing.' => 'လိုအပ်သော လိပ်စာအကွက် ပျောက်ဆုံးနေပါသည်။','Postcode or ZIP is invalid.' => 'စာတိုက်ကုဒ် သို့မဟုတ် ZIP ကုဒ် မှားယွင်းနေပါသည်။','Phone number is invalid.' => 'ဖုန်းနံပါတ် မှားယွင်းနေပါသည်။','State or county is invalid.' => 'ပြည်နယ် သို့မဟုတ် ခရိုင် မှားယွင်းနေပါသည်။','Country is invalid or has no address fields.' => 'နိုင်ငံ မမှန်ကန်ပါ သို့မဟုတ် လိပ်စာအကွက်များ မရှိပါ။','The request could not be processed.' => 'တောင်းဆိုချက်ကို စီမံဆောင်ရွက်၍မရပါ။','Back to previous step' => 'ယခင်အဆင့်သို့ ပြန်သွားပါ','Skip to settings' => 'ဆက်တင်များသို့ ကျော်သွားပါ','Start over and return to the first guided setup step' => 'အစမှပြန်စပြီး ပထမဆုံးလမ်းညွှန်ထားသော စနစ်ထည့်သွင်းမှုအဆင့်သို့ ပြန်သွားပါ','Start over' => 'ပြန်စပါ','Please complete all sub-steps before continuing.' => 'ဆက်လက်လုပ်ဆောင်ခြင်းမပြုမီ အဆင့်ခွဲအားလုံးကို ပြီးမြောက်အောင်လုပ်ပါ။','Expand' => 'ချဲ့ထွင်ပါ','Collapse' => 'ခေါက်သိမ်းရန်','Skip' => 'ကျော်သွားပါ','Mark as complete' => 'ပြီးမြောက်သည်ဟု မှတ်သားပါ','Mark as incomplete' => 'မပြီးပြတ်သေးဟု မှတ်သားပါ','View full-size image: %s' => 'ရုပ်ပုံအပြည့်အစုံကိုကြည့်ပါ- %s','Full-size setup guide image' => 'အရွယ်အစားအပြည့် စနစ်ထည့်သွင်းမှုလမ်းညွှန်ပုံ','Close image' => 'ပုံကိုပိတ်ပါ','Fluid Checkout Guided Setup' => 'Fluid Checkout လမ်းညွှန်စနစ်ထည့်သွင်းခြင်း','Welcome' => 'ကြိုဆိုပါတယ်','Explore your checkout' => 'သင့်ငွေရှင်းကောင်တာကို စူးစမ်းလေ့လာပါ','All set' => 'အားလုံး အဆင်သင့်ဖြစ်ပါပြီ','You do not have permission to access this page.' => 'ဤစာမျက်နှာကို ဝင်ရောက်ကြည့်ရှုခွင့် သင်မရှိပါ။','Go to step %1$d: %2$s' => 'အဆင့် %1$d သို့သွားပါ- %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'ဤလမ်းညွှန်စနစ်ထည့်သွင်းမှုသည် Fluid Checkout နှင့် ရင်းနှီးလာစေရန် ကူညီပေးပါသည်။ အောက်ပါအဆင့်များသည် လောလောဆယ်တွင် နေရာချန်ထားရမည့်အဆင့်များသာဖြစ်သည်။','Continue to the next step when you are ready.' => 'အဆင်သင့်ဖြစ်ပါက နောက်တစ်ဆင့်သို့ ဆက်သွားပါ။','Open your store checkout to see Fluid Checkout in action.' => 'Fluid Checkout ကို လုပ်ဆောင်ပုံကို ကြည့်ရှုရန် သင့်စတိုးဆိုင် ငွေရှင်းကောင်တာကို ဖွင့်ပါ။','View checkout page' => 'ငွေရှင်းစာမျက်နှာကို ကြည့်ရန်','You can return to Fluid Checkout settings to continue configuring your store.' => 'သင့်စတိုးကို ဆက်လက်စီစဉ်သတ်မှတ်ရန် Fluid Checkout ဆက်တင်များသို့ ပြန်သွားနိုင်ပါသည်။','Review checkout and cart settings' => 'ငွေရှင်းခြင်းနှင့် လှည်းဆက်တင်များကို ပြန်လည်သုံးသပ်ပါ','Explore add-ons from the dashboard' => 'ဒက်ရှ်ဘုတ်မှ add-on များကို လေ့လာပါ','Finish & go to settings' => 'အပြီးသတ်ပြီး ဆက်တင်များသို့ သွားပါ','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce လုပ်ထုံးလုပ်နည်းများနှင့် ကိုက်ညီစေရန် အမွေအနှစ်တန်ဖိုးမှ ငွေတောင်းခံလွှာဖုန်းအကွက် မြင်သာမှုရွေးချယ်မှုကို အပ်ဒိတ်လုပ်ပါ။','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce လုပ်ထုံးလုပ်နည်းများနှင့် ကိုက်ညီစေရန် legacy value မှ shipping phone field visibility option ကို အပ်ဒိတ်လုပ်ပါ။','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'အော်ဒါအကျဉ်းချုပ် နောက်ခံအရောင် ဆက်တင်ကို Split design secondary column background color option အသစ်သို့ ကူးယူပါ။','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Biteship plugin ကိုအသုံးပြုသည့်အခါ enhanced select fields feature ကို အမြဲပိတ်ထားသည်။','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'German Market ကိုအသုံးပြုသည့်အခါ place order position ကို &quot;order summary အောက်တွင်&quot; အမြဲသတ်မှတ်ထားသည်။ ထို plugin သည် place order ခလုတ်နှင့် legal checkbox များကို order summary အောက်တွင်ပြသရန် လိုအပ်သည်။','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce အတွက် Germanized ကိုအသုံးပြုသည့်အခါ place order position ကို &quot;Before the order summary&quot; အဖြစ် အမြဲသတ်မှတ်ထားသည်။ ထို plugin သည် place order ခလုတ်နှင့် legal checkbox များကို order summary အောက်တွင်ပြသရန် လိုအပ်သည်။','Edit pickup locations' => 'လာယူမည့်နေရာများကို တည်းဖြတ်ပါ','Use local pickup label from WooCommerce settings' => 'WooCommerce ဆက်တင်များမှ ဒေသတွင်း ကောက်ယူမှု အညွှန်းကို အသုံးပြုပါ','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'ဖွင့်ထားသည့်အခါ ငွေရှင်းသည့်အခါ ကောက်ယူမှုရွေးချယ်မှု အညွှန်းသည် WooCommerce ကောက်ယူမှုတည်နေရာဆက်တင်များမှ ခေါင်းစဉ်နှင့် ကိုက်ညီပါသည်။ ပိတ်ထားသည့်အခါ အညွှန်းသည် Fluid Checkout မှ ဘာသာပြန်နိုင်သော &quot;Local pickup&quot; စာသားကို အသုံးပြုပါသည်။','Button label for applying coupon codesApply' => 'လျှောက်ထားပါ။','Checkout step titleContact' => 'ဆက်သွယ်ရန်','Checkout step titleShipping' => 'သင်္ဘောဖြင့်ကုန်ပစ္စည်းပို့ခြင်း','Checkout step titleBilling' => 'ငွေတောင်းခံခြင်း။','Checkout step titlePayment' => 'ငွေပေးချေမှု','Checkout substep change link labelChange' => 'ပြောင်းလဲပါ။','Checkout substep save link labelSave changes' => 'အပြောင်းအလဲများကို သိမ်းဆည်းပါ။','Substep review textNone.' => 'တစ်ခုမှ','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'ပုံမရွေးပါ။','Settings sectionCart' => 'လှည်း','Settings sectionOrder pay' => 'အော်ဒါပေးရမယ်။','Settings sectionThank you' => 'ကျေးဇူးတင်ပါသည်','Settings section titleIntegrations' => 'ပေါင်းစည်းမှု','Settings section titleLicense keys' => 'လိုင်စင်သော့များ','Captcha positionBefore place order section' => 'နေရာအမှာစာ ကဏ္ဍမစမီ','Captcha positionBefore place order button' => 'အော်ဒါမတင်မီ ခလုတ်နှိပ်ပါ။','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'ပိတ်လိုက်','Log in link label at checkout contact stepLog in' => 'လော့ဂ်အင်','Log in separator label at for when guest checkout is disabledOr continue below' => 'ဒါမှမဟုတ် အောက်မှာ ဆက်သွားပါ။','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'ဒါမှမဟုတ် ဧည့်သည်အဖြစ် ဆက်သွားပါ။','Clear image selection on admin pages.Remove image' => 'ပုံကို ဖယ်ရှားပါ။','shipping packagesShipping %d' => 'ပို့ဆောင်မှု %d','shipping packagesShipping' => 'သင်္ဘောဖြင့်ကုန်ပစ္စည်းပို့ခြင်း','Used as fallb